/* Câu chép chính tả: khung phát (giây) trong audio từng part, lấy theo mốc lời thoại (sync.js); chỉ giữ câu mà chữ nghe được khớp lời thoại ≥ 80%. 01/11/2026 */
window.CAMDICT={"1":{"1":[{"s":101.26,"e":103.3,"t":"Hello, how can I help you?"},{"s":103.7,"e":110.32,"t":"I'm taking a year off and I'm hoping to travel abroad and to find work as well for part of the time."},{"s":110.88,"e":115.36,"t":"I know you specialise in student travel and work placement, so..."},{"s":115.06,"e":119.44,"t":"That's right, we can help you arrange your travel and set up a job for you."},{"s":131.76,"e":133.26,"t":"Date of birth?"},{"s":134.7,"e":136.66,"t":"Oh, I'm the 31st!"},{"s":139.38,"e":147.2,"t":"And your address? 21 Waverley Road, Radstone RD46WV."},{"s":147.22,"e":149.7,"t":"And a contact telephone number, please."},{"s":159.4,"e":163.72,"t":"Now, tell me where you plan to travel to and I'll see how I can help."},{"s":163.9,"e":166.22,"t":"Well, I'd like to go to Northern Europe."},{"s":167.68,"e":171.98,"t":"No, I know Southern Europe quite well as I've been there with my family."},{"s":172.44,"e":175.22,"t":"We always went by plane, but now I can choose."},{"s":175.48,"e":179.02,"t":"I'd like to go by train so I can stop off whenever I want."},{"s":180.2,"e":184.3,"t":"Now, just as important, what sort of work have you got in mind?"},{"s":184.54,"e":193.7,"t":"Well, I thought about hotel work because then I might get accommodation with the job and I'd like to work for about half the year."},{"s":194.58,"e":197.3,"t":"That sort of work is usually quite competitive."},{"s":197.82,"e":201.2,"t":"Perhaps you should consider an alternative just in case."},{"s":212.22,"e":216.54,"t":"You can generally earn quite good money if you're willing to work fairly long hours."},{"s":266.02,"e":271.28,"t":"To start off with, we could issue one for up to three months to cover the countries you're intending to visit."},{"s":272.78,"e":277.64,"t":"Do you have any information about youth hostels which I could use to plan my route?"},{"s":277.82,"e":280.2,"t":"Yes, I'll give you a booklet now."},{"s":279.9,"e":283.18,"t":"But it's down to you to book your accommodation."},{"s":282.88,"e":290.08,"t":"At certain times of the year, especially during public holiday periods, such places fill up fast."},{"s":297.84,"e":300.5,"t":"Although you'd probably be too tired anyway."},{"s":300.7,"e":302.3,"t":"I won't mind that."},{"s":302.42,"e":304.4,"t":"And you're going to be travelling alone?"},{"s":305.3,"e":311.28,"t":"Well, before I make any arrangements for you, you need to have insurance for your entire trip."},{"s":311.54,"e":313.74,"t":"We can arrange that for you if you like."},{"s":326.08,"e":327.94,"t":"Right, I'll do that."},{"s":328.48,"e":333.02,"t":"I thought I'd take my laptop so I can email and keep in touch with people at home."},{"s":333.88,"e":337.96,"t":"Not a good idea to lug your computer around with you."},{"s":337.94,"e":341.24,"t":"It's much more sensible to rely on an internet cafe."},{"s":341.52,"e":343.38,"t":"That's what we tell people to do."},{"s":344.56,"e":348.92,"t":"Right, so I've entered all your details, let's see what the database comes up with."}],"2":[{"s":67.07,"e":70.03,"t":"Firstly, I'll explain the plan of the store to you."},{"s":70.33,"e":78.15,"t":"The building is on seven floors and is circular, as you can see, and we're here on the ground floor in its entrance hall."},{"s":92.25,"e":93.81,"t":"That's not how we operate."},{"s":102.49,"e":105.81,"t":"We provide those so that people can sit wherever they want."},{"s":120.77,"e":128.51,"t":"We pride ourselves in being the largest bookshop in the country, so our sales assistants can't possibly know all the available titles."},{"s":139.59,"e":143.57,"t":"And just to your right, there's a door to the cloakroom, where people can leave their coats."},{"s":144.21,"e":149.59,"t":"Then after that, there's a stand where we keep a selection of local and national newspapers."},{"s":154.25,"e":159.37,"t":"We really want people to feel as though they're browsing through books in the comfort of their own home."},{"s":210.81,"e":217.03,"t":"Right, now I suggest we walk slowly up through the building, and I'll give you more information as we go."},{"s":217.37,"e":219.37,"t":"We're open 12 hours a day."},{"s":219.07,"e":223.35,"t":"We don't mind if people spend the whole day here, but leave without buying anything."},{"s":232.47,"e":235.37,"t":"Look at how busy each floor is, but how quiet."},{"s":236.13,"e":239.79,"t":"You may be wondering whether there are any children in the building."},{"s":276.71,"e":282.99,"t":"Now, we're just passing the fiction section, and you've probably noticed a small crowd of people beginning to gather."},{"s":283.37,"e":286.91,"t":"That's because a well-known author is going to read from her latest novel."},{"s":287.23,"e":292.51,"t":"We try to hold events like this at least once or twice a week, and as you can imagine, they're very popular."},{"s":309.97,"e":315.57,"t":"One of the country's best-known poets ran the workshop, and the participants read their poems aloud to him."},{"s":315.89,"e":320.43,"t":"He was kind and encouraging, and many people felt inspired by his advice."},{"s":320.77,"e":326.57,"t":"It's extremely difficult to earn your living as a professional poet, and even published poets have other jobs."}],"3":[{"s":54.69,"e":61.51,"t":"Thanks, Ron, for coming to my office to discuss the presentation you gave yesterday to the business management seminar."},{"s":61.21,"e":67.13,"t":"We'll go over what you did with the aim of helping you improve your next presentation."},{"s":90.97,"e":94.91,"t":"Henry Ford and his cars, in fact, at the turn of the 20th century."},{"s":94.61,"e":102.89,"t":"And later, a big US supermarket chain used it, and this was where Toyota in Japan got the idea for its car making."},{"s":103.31,"e":105.49,"t":"Yes, that would have been a good addition."},{"s":106.27,"e":114.63,"t":"Now, before we go any further, I think I would suggest that you should have stopped and clearly defined just-in-time for your seminar colleagues."},{"s":129.59,"e":137.17,"t":"But you never told us that JIT simply means waiting until the last moment to order new supplies as you need them."},{"s":137.27,"e":138.81,"t":"Yes, you're right."},{"s":140.87,"e":146.15,"t":"Now, you talked a bit about standardising parts as a way of streamlining JIT."},{"s":146.41,"e":148.49,"t":"Where did you get your data from?"},{"s":148.35,"e":155.35,"t":"Well, I tried an internet website on the subject which is called The Lean Clearinghouse, but it was too technical for me."},{"s":155.73,"e":160.25,"t":"So, in the end, I got my data from a textbook called Learning from Toyota."},{"s":160.53,"e":164.69,"t":"I found some journal articles too, but they didn't seem very useful."},{"s":165.21,"e":169.39,"t":"Yes, well, there is a US government report on it I've seen."},{"s":171.95,"e":173.85,"t":"I look forward to reading through it."},{"s":174.23,"e":179.75,"t":"And while you're at it, you might want to find out about cases where JIT might not be suitable."},{"s":180.45,"e":188.73,"t":"And that's in service industries like tourism or healthcare, where customers are paying for something that they can't actually see or count."},{"s":201.91,"e":203.29,"t":"I'll see what I can find out."},{"s":252.84,"e":259.98,"t":"Now, unless you have any more questions, let's turn to a critique of the technical aspects of the presentation."},{"s":260.38,"e":264.28,"t":"I'm afraid I'll emphasise the things I think you might want to work on."},{"s":264.66,"e":269.78,"t":"It was a good talk, but with a little work, your next presentation should be excellent."},{"s":272.24,"e":274.76,"t":"Actually, I wasn't happy with my delivery."},{"s":274.94,"e":278.46,"t":"I sometimes seemed to talk fast and sometimes slow."},{"s":278.74,"e":280.2,"t":"I was on edge, I guess."},{"s":282.0,"e":285.74,"t":"And as well as that, your purpose wasn't very specific."},{"s":286.4,"e":291.18,"t":"In future, you need to lay out exactly what you're going to cover and why."},{"s":291.58,"e":294.84,"t":"Make it clear and concise and not so general."},{"s":299.14,"e":302.16,"t":"Well, you didn't link the sections, did you?"},{"s":302.26,"e":304.88,"t":"You went too quickly from one to the next."},{"s":305.2,"e":306.9,"t":"It was all just too abrupt."},{"s":307.0,"e":308.96,"t":"Okay, I'll try to improve that."},{"s":322.12,"e":329.3,"t":"And, you know, another thing, I could see from the other students' reactions, they just didn't understand some of the vocabulary I was using."},{"s":331.2,"e":335.66,"t":"Well, remember, your audience were laymen, mostly without knowledge of JIT."},{"s":336.14,"e":340.58,"t":"So, you need to simplify and try to put things in everyday English."},{"s":343.78,"e":346.7,"t":"And lastly, I'll just mention your body language."},{"s":347.34,"e":352.52,"t":"You didn't use gestures and you just stood straight without any animation."},{"s":353.2,"e":355.96,"t":"It didn't make you seem very interested in the subject."},{"s":356.08,"e":359.34,"t":"I know, even though I really do like the subject."},{"s":360.88,"e":366.58,"t":"Well, despite all this, I enjoyed your presentation and I could see you put lots of work into it."},{"s":367.16,"e":370.36,"t":"I look forward to an even better presentation from you next time."},{"s":370.06,"e":372.3,"t":"Well, thanks for your help."}],"4":[{"s":36.77,"e":41.01,"t":"It's a condition that affects children's ability to understand and work with numbers."},{"s":41.93,"e":48.95,"t":"Currently, most schools use the traditional method of teaching mathematics, which may not be effective for children with Dyscalculia."},{"s":49.27,"e":56.91,"t":"These children struggle with grasping mathematical concepts, especially when it comes to understanding the concept of time and sequence."},{"s":57.61,"e":62.17,"t":"They find it challenging to comprehend the passage of time and the order in which events occur."},{"s":62.73,"e":69.67,"t":"In the classroom, teachers focus on providing everyday practical examples to help these children overcome their difficulties."},{"s":70.03,"e":76.99,"t":"They engage the students in activities that involve dealing with money, as this is a common challenge for children with Dyscalculia."},{"s":77.23,"e":84.49,"t":"By incorporating real-life scenarios, teachers aim to make the learning experience more meaningful and relatable for these students."},{"s":84.69,"e":90.77,"t":"Additionally, teachers provide individualised support and interventions tailored to each student's needs."},{"s":91.17,"e":97.89,"t":"To boost their confidence, children with mathematics disorders are encouraged to practise more calculations and problem-solving."},{"s":98.29,"e":104.81,"t":"This additional practise helps them develop a stronger sense of self-assurance when it comes to dealing with mathematical tasks."},{"s":105.05,"e":110.07,"t":"Teachers also provide positive reinforcement and praise for their efforts and progress."},{"s":110.11,"e":117.53,"t":"Teachers also implement strategies that encourage children to make educated guesses when they encounter mathematical problems."},{"s":118.03,"e":127.43,"t":"By empowering them to make informed guesses, teachers hope to foster problem-solving skills and reduce anxiety associated with mathematical challenges."},{"s":128.35,"e":138.53,"t":"Additionally, they incorporate various exercises, such as breathing techniques, relaxation exercises, and even walking breaks, to promote a conducive learning environment."},{"s":139.11,"e":144.13,"t":"These activities aid in reducing stress and promoting focus during math lessons."},{"s":144.39,"e":152.33,"t":"Teachers also explore alternative teaching methods, such as visual aids and manipulatives, to enhance understanding and engagement."},{"s":153.39,"e":161.63,"t":"Researchers in this field are particularly interested in finding a potential link between Dyscalculia and language learning difficulties."},{"s":162.31,"e":168.73,"t":"They are investigating whether there is a connection between language barriers and the challenges children face in mathematics."},{"s":168.43,"e":174.81,"t":"Understanding this link could help inform more targeted interventions and support strategies."},{"s":175.63,"e":180.37,"t":"Children with Dyscalculia often struggle with concentration and maintaining focus."},{"s":181.15,"e":188.59,"t":"Teachers are aware of this issue and work to provide additional support and accommodations to help these children stay engaged during lessons."},{"s":189.01,"e":195.89,"t":"They may use techniques like chunking information, breaking tasks into smaller steps, and providing regular breaks."},{"s":206.91,"e":215.21,"t":"By implementing these strategies, children may no longer require additional treatment or training specifically focused on their mathematics disorder."},{"s":215.71,"e":223.29,"t":"Ongoing assessment and monitoring of progress are crucial to ensure the effectiveness of interventions and make any necessary adjustments."},{"s":222.99,"e":229.57,"t":"It's important to note that Dyscalculia affects not only the children, but also their families and teachers."},{"s":229.87,"e":237.75,"t":"Teachers and families play a crucial role in supporting these children and understanding their unique needs in the classroom and at home."},{"s":238.41,"e":247.67,"t":"Open communication, collaboration, and a supportive environment are key in helping children with Dyscalculia thrive academically and emotionally."},{"s":247.99,"e":255.73,"t":"By recognising and addressing Dyscalculia, we can provide a more inclusive and supportive learning environment for all students."}]},"2":{"1":[{"s":84.1,"e":89.52,"t":"Yes, I'd like to apply for one of the lifeguard jobs you advertised this week."},{"s":89.96,"e":92.88,"t":"Right, we can do that now over the phone."},{"s":93.06,"e":95.32,"t":"I'll just need some information from you."},{"s":95.94,"e":97.34,"t":"Let me get a form."},{"s":98.28,"e":101.6,"t":"Okay, so let's start with your name."},{"s":102.38,"e":107.3,"t":"Peter Smith Okay, can you let me have your home address?"},{"s":107.0,"e":112.7,"t":"It's 130 South Main Street, Lake Elsinore."},{"s":113.12,"e":116.84,"t":"Okay, I'm new around here."},{"s":116.84,"e":118.52,"t":"Can you spell that for me?"},{"s":119.32,"e":124.96,"t":"Yes, it's E-L-S-I-N-O-R-E."},{"s":125.8,"e":128.88,"t":"Okay, got that."},{"s":129.3,"e":130.7,"t":"And your phone number?"},{"s":147.52,"e":152.5,"t":"Okay, now what do you do?"},{"s":152.2,"e":155.82,"t":"Are you still in college or are you working full time?"},{"s":156.18,"e":162.8,"t":"I'm in my second year here at Fernley, and this vacation I've got a job as a part-time waiter."},{"s":162.94,"e":167.6,"t":"Okay, I guess if you're at Fernley College you'll be studying physical education?"},{"s":167.62,"e":169.58,"t":"They all seem to do that there."},{"s":170.56,"e":175.64,"t":"Then I hope to go on and coach baseball in high school, something like that."},{"s":175.74,"e":178.82,"t":"I guess it all depends on how I do in my final exams."},{"s":178.52,"e":180.9,"t":"Okay, sounds good to me."},{"s":227.94,"e":231.54,"t":"Now, the next part of the form deals with qualifications."},{"s":231.96,"e":234.28,"t":"Do you have the water safety certificate?"},{"s":234.6,"e":236.8,"t":"We absolutely insist on that."},{"s":238.06,"e":241.76,"t":"So how long will it last before you have to do a refresher course?"},{"s":242.0,"e":245.2,"t":"I took it last November, so it'll run out in October."},{"s":247.16,"e":250.24,"t":"Now, what about work experience as a lifeguard?"},{"s":250.58,"e":253.56,"t":"Well, I've had about four months' experience."},{"s":253.94,"e":256.06,"t":"Which swimming pool was that at?"},{"s":256.08,"e":260.22,"t":"I need to have details of your employer, obviously, so we can get a reference."},{"s":260.44,"e":262.84,"t":"Oh, it was at the beach here in Fernley."},{"s":263.16,"e":266.22,"t":"I can get the number of the person you need to contact."},{"s":267.48,"e":272.46,"t":"And do you have any other additional skills I can put down?"},{"s":275.7,"e":279.72,"t":"I'm also keen on rock climbing, but that's not really relevant here."},{"s":282.2,"e":285.56,"t":"And I need to ask when you would prefer to work."},{"s":285.76,"e":290.36,"t":"You can choose either Saturday mornings or any time Monday to Friday."},{"s":290.88,"e":293.26,"t":"We've got enough people on Sundays at the moment."},{"s":294.1,"e":298.42,"t":"Well, not Monday to Friday, because I'm at the restaurant weekday evenings."},{"s":300.04,"e":301.36,"t":"We open at six."},{"s":301.84,"e":303.18,"t":"Could you start that early?"},{"s":304.88,"e":306.62,"t":"I prefer that to working late."},{"s":318.9,"e":323.92,"t":"Now, before you go, I'd just like to ask you how you found out about our advertisement."},{"s":323.62,"e":325.76,"t":"We always ask this."},{"s":325.46,"e":327.66,"t":"Was it from the newspaper or the radio?"},{"s":328.02,"e":331.44,"t":"I heard the advertisement this morning when I was driving into college."},{"s":331.74,"e":333.54,"t":"I don't usually read the local paper."},{"s":335.72,"e":337.3,"t":"Well, that's all."},{"s":337.5,"e":338.94,"t":"Hope to see you soon."}],"2":[{"s":98.14,"e":100.38,"t":"Arthur, welcome to the programme."},{"s":101.42,"e":105.1,"t":"So, Arthur, what advice do you have for our listeners?"},{"s":105.36,"e":112.12,"t":"Well, one thing I've heard people say is that when you're starting up a business, you can't afford to make mistakes."},{"s":112.48,"e":118.66,"t":"Well, I believe in the old saying, a person who never made a mistake never made anything."},{"s":129.12,"e":132.1,"t":"You need to be able to cope with the world of business."},{"s":132.48,"e":140.28,"t":"But according to recent American business school studies, believing in yourself isn't enough by itself to guarantee success."},{"s":141.1,"e":146.42,"t":"Confidence can be a good thing, but a person can have too much confidence."},{"s":146.96,"e":154.24,"t":"And people who try to learn to be confident by buying those how-to-succeed books are just wasting their time."},{"s":154.98,"e":163.4,"t":"The advice given in these American studies was that being a successful entrepreneur comes down to having the right attitude."},{"s":163.98,"e":168.12,"t":"It's no good getting depressed every time something goes wrong."},{"s":167.82,"e":172.0,"t":"Always keep your goals in mind and never give up."},{"s":172.3,"e":177.84,"t":"And don't listen to all the people around you who say, oh, this will never work."},{"s":179.08,"e":183.84,"t":"One thing I've learned in business is that you don't have to be an expert in everything."},{"s":184.14,"e":185.74,"t":"Marketing, for example."},{"s":186.22,"e":189.74,"t":"When I started my business, I tried to do it all myself."},{"s":198.6,"e":204.68,"t":"So, I got someone who knew more about this to take care of the marketing side of things for me."},{"s":213.56,"e":218.54,"t":"You have to be able to control people, but listen to them at the same time."},{"s":218.24,"e":226.54,"t":"Some people are driven to make their companies successful, but that too often leads to a ruthless approach."},{"s":227.12,"e":231.98,"t":"Then there's the question of taking risks, even calculated ones."},{"s":232.48,"e":239.36,"t":"I personally feel it's actually better to tread carefully when it comes to taking short-term risks."},{"s":239.54,"e":246.92,"t":"You need a degree of vision, certainly, but it's easy to get carried away by your desire to increase profits."},{"s":247.42,"e":251.94,"t":"And if things go wrong, you can end up losing more than you gain."},{"s":288.57,"e":293.51,"t":"So, if you have a great idea for a business, what should you do next?"},{"s":293.85,"e":299.65,"t":"Well, the first thing to ask yourself is whether there's a need for your product or service."},{"s":304.35,"e":311.81,"t":"You don't need to worry about whether it's original or not because there isn't always enough of a demand for completely new ideas."},{"s":325.65,"e":328.87,"t":"Because realistically, that's how long it will take."},{"s":348.99,"e":353.91,"t":"If I'd listened to the business advice I was given back then, I'd never have got started."},{"s":370.77,"e":376.13,"t":"The first couple of years were very tough, but I knew I would make it eventually."}],"3":[{"s":78.03,"e":81.81,"t":"Is it OK with you if we have a chat together before we go and see him?"},{"s":83.51,"e":88.85,"t":"So did you choose this university to do performance arts because it's got such a good reputation?"},{"s":89.33,"e":90.75,"t":"That's what hooked me in."},{"s":104.45,"e":110.95,"t":"So, even though I was tempted to go and study abroad, I decided to come here in the end."},{"s":112.97,"e":117.89,"t":"No, it's been brilliant, especially the options this year."},{"s":118.63,"e":124.07,"t":"The body and dance option I did for this term has been particularly stimulating."},{"s":124.53,"e":130.69,"t":"I'm sorry I didn't go for that one too, but I did dance and drama, which was brilliant too."},{"s":131.05,"e":136.73,"t":"I think the most valuable option I've done was the movement analysis course we did in the first year."},{"s":138.65,"e":143.51,"t":"It's provided a great foundation for all our other work since then."},{"s":143.87,"e":147.65,"t":"So let's talk about our work experience last summer."},{"s":148.25,"e":150.73,"t":"You went to Finland, didn't you?"},{"s":152.13,"e":154.53,"t":"I was at their National Ballet Theatre."},{"s":173.59,"e":177.87,"t":"I've been offered more work at the place where I was working in Canada."},{"s":179.51,"e":182.67,"t":"So what do you think you gained most from the experience?"},{"s":183.39,"e":186.99,"t":"I think I've got much better at controlling my stress levels."},{"s":187.29,"e":195.99,"t":"For me, it was probably the fact that I learned a lot about collaborating with others rather than working independently."},{"s":196.35,"e":201.77,"t":"I was lucky to be able to do that in a situation that wasn't too stressful."},{"s":202.89,"e":209.39,"t":"Also, I had to organise my time well, but I've always been reasonably good at that."},{"s":210.81,"e":214.45,"t":"So we've got quite a few things ready to say to our tutor."},{"s":219.23,"e":224.13,"t":"I also think it could be helpful to discuss our future plans."},{"s":224.69,"e":229.53,"t":"For example, what we're planning to do our dissertations on."},{"s":230.97,"e":236.29,"t":"I was unsure about whether to focus on globalisation in dance or on stage design."},{"s":236.99,"e":241.89,"t":"I did an essay on globalisation in my first year and really enjoyed it."},{"s":241.77,"e":248.31,"t":"But then I saw a spectacular production at the Royal Opera House, and that settled me on stage design."},{"s":249.01,"e":254.37,"t":"I know another student who's planning to work on that too, so we can discuss things together a bit."},{"s":256.93,"e":262.95,"t":"I'm planning to do something on current trends in contemporary dance for my dissertation."},{"s":263.35,"e":264.99,"t":"That sounds pretty challenging."},{"s":267.41,"e":270.79,"t":"It might not be easy to organise in a coherent way."},{"s":275.97,"e":280.23,"t":"And I feel confident about how to write a longer piece of work."},{"s":280.83,"e":286.09,"t":"I'm in a bit of a panic, though, about how I'll get through all the literature."},{"s":286.75,"e":288.69,"t":"There seems to be so much."},{"s":289.01,"e":291.65,"t":"Hopefully it won't all be relevant."},{"s":328.96,"e":331.64,"t":"So, have you made any career plans yet?"},{"s":332.08,"e":333.94,"t":"I'm still undecided."},{"s":334.5,"e":337.12,"t":"I've thought about performance, of course."},{"s":336.82,"e":340.84,"t":"Yes, I think lots of graduates from here take that route."},{"s":341.18,"e":347.62,"t":"But it's a hard life, involving lots of tough, repetitive practise, as well as actually appearing on stage."},{"s":347.54,"e":355.62,"t":"Yes, but the performance I've met know that's essential for the job and say they wouldn't change what they do for the world."},{"s":356.12,"e":363.58,"t":"I know lots of graduates go into education, teaching at various levels, but that means doing some kind of post-grad certificate."},{"s":366.82,"e":371.84,"t":"I was wondering about theatre management as a possible option."},{"s":372.26,"e":375.34,"t":"That's what our tutor did before he got into teaching, isn't it?"},{"s":375.22,"e":379.14,"t":"Yes, but he said he quickly realised it wasn't for him."},{"s":379.48,"e":381.64,"t":"He wasn't earning enough to live on."},{"s":382.06,"e":387.04,"t":"I can imagine his communication skills are better than his business skills as well."},{"s":391.0,"e":398.08,"t":"I've read something saying it can be an interesting career, though I don't think many graduates go for this."},{"s":398.76,"e":404.66,"t":"But that might mean there's not so much competition, as in many other fields of dance."},{"s":405.88,"e":407.72,"t":"So, now shall we make a list?"}],"4":[{"s":83.62,"e":86.32,"t":"You may be wondering why we've been studying this animal."},{"s":96.4,"e":102.74,"t":"Up until 1892, the population of these animals was severely depleted because of hunting."},{"s":103.2,"e":104.9,"t":"That's no longer allowed."},{"s":105.28,"e":107.54,"t":"But today there is a new danger."},{"s":107.86,"e":114.38,"t":"Sea lions often forage for food in the same areas along the coastlines where there are nets used to catch sharks."},{"s":115.06,"e":119.26,"t":"Unfortunately, they tend to get caught up in the nets by accident and drown."},{"s":127.08,"e":133.82,"t":"There are several different animal tracking methods, which vary in their effectiveness, and there are different factors to consider."},{"s":134.68,"e":141.42,"t":"One of the most important of these is the cost, but you also have to consider how easy your chosen method is to use."},{"s":141.68,"e":145.36,"t":"You may choose a traditional method, like a plastic tag."},{"s":153.3,"e":161.5,"t":"You might also go with a more modern method like GPS tracking, which uses satellite technology to transmit data on the animal around the clock."},{"s":162.26,"e":167.24,"t":"One drawback for marine animals, though, is that they don't transmit a signal in the ocean."},{"s":167.72,"e":170.14,"t":"You only get data when they're on land."},{"s":170.92,"e":175.62,"t":"There are certain large animals in remote areas that have to be tracked using a helicopter."},{"s":176.18,"e":178.18,"t":"The polar bear is a good example."},{"s":178.54,"e":183.26,"t":"Now, an important part of tracking is being able to clearly identify the animal."},{"s":183.82,"e":187.92,"t":"Some, like zebras, are identified by markings such as their stripes."},{"s":188.48,"e":193.1,"t":"While the dolphin usually has distinguishing scars on its body that can help tell them apart."},{"s":193.96,"e":199.9,"t":"Sea lions don't have any markings like this, which is just one of the challenges of tracking them."},{"s":211.54,"e":214.48,"t":"This was something the researchers hadn't anticipated."},{"s":215.4,"e":220.1,"t":"Researchers in California studying American sea lions tried a different method."},{"s":220.9,"e":223.12,"t":"They applied paint to the animals."},{"s":223.76,"e":227.56,"t":"They thought this would be a better, less invasive means of identification."},{"s":241.31,"e":243.17,"t":"So let's look at our current study."},{"s":243.61,"e":246.19,"t":"We have several aims that we'd like to achieve."},{"s":246.55,"e":252.41,"t":"The first of these is to try to establish whether sea lions can be identified from the whiskers on their face."},{"s":253.15,"e":256.53,"t":"These are much coarser than a cat's whiskers, so easier to see."},{"s":256.85,"e":263.57,"t":"Our theory is that the pattern of these whiskers may be as individual as a fingerprint on a human."},{"s":264.29,"e":269.95,"t":"If this is in fact true, then we think this could be an effective way to identify them."},{"s":278.77,"e":282.11,"t":"We're using a few different methods to help us do all this."},{"s":282.59,"e":285.87,"t":"We know that we need to build up a wide range of visual data."},{"s":286.23,"e":293.89,"t":"So firstly, we've been in touch with zoos around Australia to gather photographs from them of the faces of any sea lions they have."},{"s":294.49,"e":301.77,"t":"This won't be enough to achieve our purpose though, so we're also broadening our search by inviting the public to take part in our research."},{"s":302.53,"e":306.73,"t":"We're hoping this will result in hundreds of useful images we can use."}]},"3":{"1":[{"s":95.72,"e":99.52,"t":"You will see that there is an example that has been done for you."},{"s":113.38,"e":116.98,"t":"I'm hoping you'll be able to help me organise a trip to Beachheads."},{"s":117.2,"e":121.52,"t":"Sure, let me just fill in our customer request sheet while I'm speaking to you."},{"s":121.78,"e":123.96,"t":"Could you tell me your name again, please?"},{"s":123.66,"e":125.6,"t":"Yes, it's Duncan."},{"s":130.22,"e":136.64,"t":"The man's name is Duncan White, so White has been written in the space."},{"s":137.88,"e":139.46,"t":"Now we shall begin."},{"s":157.04,"e":158.72,"t":"Hi, my name's Duncan."},{"s":162.98,"e":167.1,"t":"Sure, let me just fill in our customer request sheet while I'm speaking to you."},{"s":167.66,"e":169.52,"t":"Could you tell me your name again, please?"},{"s":169.76,"e":171.16,"t":"Yes, it's Duncan."},{"s":175.76,"e":184.52,"t":"No, there's three adults, myself, my wife and my mother, and our two daughters, Chloe and Eden."},{"s":184.78,"e":186.66,"t":"So when are you thinking of travelling?"},{"s":186.66,"e":188.46,"t":"During the next school holidays."},{"s":188.42,"e":191.94,"t":"So they start on the 12th of October, don't they?"},{"s":191.94,"e":196.76,"t":"Yes, but we'll be arriving on the 15th and we want to stay for a fortnight."},{"s":196.86,"e":198.32,"t":"Right, got all that."},{"s":198.4,"e":204.1,"t":"Now I'll just take a few notes about the type of holiday you want so I can make the bookings for you."},{"s":204.32,"e":206.96,"t":"Have you thought about where you want to stay while you're here?"},{"s":206.86,"e":213.68,"t":"In the first week, we'd like a bit of luxury and we're planning on staying in a hotel on the beach if possible."},{"s":213.9,"e":216.14,"t":"That'll be so much better than a campsite."},{"s":216.28,"e":221.58,"t":"We usually stay in a tent when we go away, but we're going to treat ourselves this time."},{"s":221.74,"e":225.8,"t":"And do you have a figure in mind for how much you'd like to spend?"},{"s":237.3,"e":243.5,"t":"I'll just have to stop myself thinking that when we go camping we only pay about $200 for a whole week."},{"s":243.76,"e":245.72,"t":"Well, I'm sure it will be worth it."},{"s":245.78,"e":248.92,"t":"I can also organise some activities for your first week."},{"s":249.18,"e":252.24,"t":"Is there anything your daughters would particularly like to do?"},{"s":252.24,"e":254.8,"t":"They want to try sailing this year."},{"s":254.74,"e":256.3,"t":"Last year it was surfing."},{"s":256.0,"e":257.86,"t":"They were mad about it."},{"s":257.56,"e":260.44,"t":"Kids change their minds a lot, don't they?"},{"s":260.2,"e":262.2,"t":"Mine are into cycling at the moment."},{"s":262.66,"e":264.58,"t":"I know someone who can teach them to sail."},{"s":264.52,"e":266.9,"t":"Would you like me to organise a class for them?"},{"s":267.9,"e":269.9,"t":"We're bringing our own boat with us."},{"s":270.02,"e":271.9,"t":"And what about your wife and your mother?"},{"s":271.86,"e":278.74,"t":"Well, my mother Susan goes bowling when she's in Brisbane but my wife Jenny doesn't really like it."},{"s":278.44,"e":282.98,"t":"She loves bushwalking but obviously my mother can't manage that."},{"s":283.18,"e":285.18,"t":"Can I suggest golf for them both?"},{"s":285.26,"e":287.06,"t":"It's a gentler kind of walk."},{"s":287.24,"e":290.66,"t":"There's a beautiful course here with magnificent views of the sea."},{"s":294.68,"e":297.76,"t":"Could you send me some leaflets about fishing in the area?"},{"s":297.88,"e":299.8,"t":"I'd like to take the boat out myself."},{"s":299.96,"e":302.24,"t":"Sure, there are some good spots around."},{"s":338.73,"e":340.97,"t":"We want something totally different."},{"s":341.17,"e":344.01,"t":"We'd like to stay up in the mountains in the National Park."},{"s":345.33,"e":347.65,"t":"And what kind of accommodation are you thinking of?"},{"s":347.53,"e":349.77,"t":"There are some beautiful houses you can rent."},{"s":354.47,"e":358.35,"t":"Is there anything a bit cheaper, say a caravan or even a cabin?"},{"s":358.37,"e":364.65,"t":"It'd have to be a caravan because they don't have cabins at the campground but the standard is very high."},{"s":364.55,"e":369.63,"t":"How much does it cost? $100 a night but they're very roomy with all mod cons."},{"s":370.01,"e":372.87,"t":"The campground's also in a really good spot."},{"s":373.39,"e":376.51,"t":"What activities are you thinking of doing in that second week?"},{"s":376.21,"e":382.75,"t":"Well, it's actually going to be my wife's birthday so I'd like to do something a bit special for her."},{"s":383.03,"e":386.57,"t":"I can book a really nice massage for her after lunch on that day."},{"s":387.39,"e":391.87,"t":"Or would she rather try something more adventurous like a walk in the treetops?"},{"s":392.07,"e":393.61,"t":"It's really exciting."},{"s":393.73,"e":395.97,"t":"You go along a really high wooden bridge."},{"s":395.81,"e":398.09,"t":"Oh no, she'd be terrified."},{"s":397.79,"e":399.99,"t":"Stick with your first idea."},{"s":400.49,"e":403.49,"t":"Are there any nice places to eat near the campground?"},{"s":409.47,"e":411.59,"t":"I've got two very fussy daughters."}],"2":[{"s":58.19,"e":64.23,"t":"Thank you for all coming to today's information session on bicycle use in the inner city."},{"s":71.63,"e":78.11,"t":"We want to provide people who don't own a bike a convenient way to get around the inner city."},{"s":85.63,"e":91.09,"t":"Just go to the City Council website and follow the prompts and you'll be sent a card."},{"s":91.47,"e":97.55,"t":"Once you've done that, you can unlock one of our bikes from any station in the inner city area."},{"s":98.03,"e":101.35,"t":"Just go to the station and log on at the computer terminal."},{"s":108.21,"e":110.01,"t":"You don't need a password or anything."},{"s":110.89,"e":116.15,"t":"Once you've chosen your bike, you can then go to where the bikes are stored and push the release button."},{"s":115.85,"e":120.69,"t":"After you do that, you have about 10 seconds to take the bike out of the rack."},{"s":121.17,"e":123.69,"t":"You can now start your bike ride."},{"s":124.17,"e":129.85,"t":"Further down the track, we're thinking about adding lockers for bags if the scheme is popular."},{"s":137.87,"e":139.97,"t":"Well, the answer is yes, you do."},{"s":145.85,"e":151.97,"t":"Now, at the end of your trip, just come back to one of the city cycle stations and wheel the bike into the bike rack."},{"s":152.35,"e":158.51,"t":"It's important to make sure that the bike is properly secured because you could be held liable if it goes missing."},{"s":209.8,"e":216.34,"t":"Let's turn to another initiative, the layout of the new Council Bicycle Centre, which will be opening next week."},{"s":217.02,"e":219.6,"t":"This is for people who already own a bike."},{"s":219.78,"e":225.8,"t":"We wanted to provide a place for cyclists to store their bikes, then change before going on to work."},{"s":226.56,"e":227.88,"t":"Can you all see the plan?"},{"s":228.38,"e":234.62,"t":"If you look at the bottom towards the right-hand corner, you'll see where the cyclists enter the centre."},{"s":238.46,"e":240.44,"t":"That's why you'll see a coffee cart."},{"s":240.94,"e":245.4,"t":"That's it there between the reception desk and the vending machines."},{"s":245.84,"e":249.36,"t":"I'm sure it'll be very popular with commuters first thing in the morning."},{"s":250.34,"e":258.22,"t":"Now, of course, some of our cyclists have very expensive bikes, so we'll have a totally secure place for them to park."},{"s":258.8,"e":261.5,"t":"That's it in the top right-hand corner."},{"s":262.02,"e":266.1,"t":"Now, there's another special service for the cyclists that I'd like to show you."},{"s":266.44,"e":268.82,"t":"Look back at the entry on the map."},{"s":269.28,"e":275.2,"t":"Just to the left of reception, on the Donovan Street side of the building, you'll see quite a large room."},{"s":275.6,"e":281.32,"t":"That's the workshop, where cyclists will be able to leave their bikes for repairs while they are at work."},{"s":282.02,"e":285.06,"t":"We've put a lot of thought into the facilities of the centre."},{"s":285.42,"e":289.1,"t":"If you have any valuables with you, you can leave these in our lockers."},{"s":297.74,"e":300.68,"t":"We've installed 10 state-of-the-art power showers."},{"s":300.82,"e":306.42,"t":"They are located in this room here, to the left of the hairdryers and just near the exit."},{"s":306.82,"e":312.82,"t":"There's also a water cooler available, so you can grab a drink and then pick up a towel next to the water cooler there."}],"3":[{"s":66.92,"e":71.26,"t":"Well, first we must clarify what renewable energy is."},{"s":82.16,"e":86.74,"t":"And I've found some very interesting examples of products using these sources."},{"s":86.64,"e":87.98,"t":"So have I."},{"s":89.5,"e":96.32,"t":"Well, the first one is a company in Germany which is producing huge kites that pull ships along."},{"s":96.72,"e":102.38,"t":"The kites are attached by long cables and they fly up to 500 metres above the sea."},{"s":102.66,"e":104.5,"t":"They must be pretty big."},{"s":104.28,"e":108.64,"t":"And it means that they can be powered by the wind no matter what the weather."},{"s":108.9,"e":110.56,"t":"That sounds like a good idea."},{"s":110.94,"e":114.0,"t":"But will they really help reduce energy use?"},{"s":125.24,"e":132.86,"t":"The company believes these kites could cut the use of these fuels by 50% and reduce the emissions by the same amount."},{"s":134.6,"e":138.98,"t":"And I found a company in the US which is developing a new type of car."},{"s":139.36,"e":145.26,"t":"Apparently they're producing a sports car which doesn't use petrol at all, just electricity."},{"s":144.96,"e":147.54,"t":"But for the US market only."},{"s":148.38,"e":150.76,"t":"Do we know what it'll look like?"},{"s":150.68,"e":158.08,"t":"They're very secretive about it and all they say is that it won't look ugly and it'll have zero emissions."},{"s":159.3,"e":160.86,"t":"So they say."},{"s":160.56,"e":162.28,"t":"Any other products?"},{"s":162.84,"e":170.12,"t":"I found an interesting article about a man in South Africa who's selling stoves using ethanol to the local people."},{"s":170.84,"e":174.38,"t":"Yes, it's made from the sugar of certain crops."},{"s":174.66,"e":181.38,"t":"Most of the local people use paraffin stoves at the moment and they are dangerous because they can explode quite easily."},{"s":183.14,"e":189.88,"t":"Now for the next part, we have to do a survey to find out how aware the public is about this kind of energy."},{"s":192.9,"e":197.7,"t":"I think it's easier to do a survey of the general public rather than local companies."},{"s":207.0,"e":208.3,"t":"Oh, I forgot that."},{"s":209.26,"e":214.0,"t":"What about the other students and the lecturers here in the university?"},{"s":214.48,"e":216.26,"t":"You know what the lecturers are like."},{"s":216.36,"e":218.5,"t":"They're so busy, they won't have the time."},{"s":218.2,"e":220.12,"t":"But the students will, I'm sure."},{"s":220.64,"e":225.74,"t":"And as well as that, we could target the local schools like last time."},{"s":225.72,"e":227.56,"t":"School kids just love doing surveys."},{"s":227.88,"e":231.0,"t":"I think we want to stick to adults for this, don't you?"},{"s":230.9,"e":232.74,"t":"You're probably right."},{"s":233.2,"e":239.36,"t":"Maybe we could approach people who rent or own properties around here since they're the ones who have to pay for the energy."},{"s":294.12,"e":298.46,"t":"Now, what about the kind of questions we want to include in the survey?"},{"s":298.16,"e":305.58,"t":"Well, we need to find out if they know what renewable energy is and how familiar people are with the concept."},{"s":306.16,"e":311.24,"t":"I know it's been all over the news lately, but I think a lot of people are still in the dark about it."},{"s":312.64,"e":314.24,"t":"I'm not sure I agree."},{"s":314.8,"e":316.76,"t":"But we can have that in if you want."},{"s":328.16,"e":329.46,"t":"And what they cost."},{"s":329.76,"e":331.18,"t":"That's not so important."},{"s":331.7,"e":336.98,"t":"But we ought to see what they think is going to happen to the consumption of traditional energy sources."},{"s":338.86,"e":340.58,"t":"Then there's nuclear power."},{"s":340.68,"e":345.62,"t":"That's an interesting one because it's cleaner and more efficient in many ways than other fuels."},{"s":345.6,"e":348.68,"t":"But the safety factor has always worried people."},{"s":349.7,"e":356.0,"t":"I know that the technology has improved greatly since it was first used, but I don't think everyone is convinced."},{"s":355.7,"e":358.6,"t":"Are there any problems with renewable energy?"},{"s":360.26,"e":362.72,"t":"And we need to know what people think about them."},{"s":363.18,"e":368.36,"t":"One argument is that it's going to be too expensive to use solar or wind power."},{"s":368.62,"e":373.92,"t":"But once people realise the benefits to us all, the price is bound to come down."},{"s":374.1,"e":376.46,"t":"It's always expensive to start with."},{"s":376.54,"e":379.9,"t":"Once enough people want it, it'll be a viable prospect."},{"s":381.4,"e":383.86,"t":"But the other thing is they don't like it."},{"s":384.22,"e":388.86,"t":"They say that some of the technology is ugly, like the big windmills used."},{"s":389.14,"e":392.74,"t":"A lot of people think they spoil the countryside, and I agree."},{"s":392.72,"e":394.54,"t":"They're not that bad."},{"s":394.52,"e":400.96,"t":"They're pretty efficient, so perhaps it's a case of choosing the right place for them where they look least out of place."}],"4":[{"s":89.38,"e":92.08,"t":"I looked at some research on absence from work."},{"s":92.32,"e":96.4,"t":"That is, the number of days' work people miss for various reasons."},{"s":99.98,"e":105.18,"t":"Frequent absence, which is obviously a more serious problem, and occasional absence."},{"s":105.6,"e":111.52,"t":"A lot of studies look at the factors involved in absence from work, and several have been identified."},{"s":112.14,"e":117.86,"t":"Firstly, the gender of the employee may influence his or her ability to attend work."},{"s":118.32,"e":125.82,"t":"For example, a female is more likely to have child care responsibility, and so could be absent as a result of that."},{"s":126.44,"e":131.8,"t":"The next factor that has been identified is the attitude of employees toward their work."},{"s":158.5,"e":162.62,"t":"And then there are factors related to the type of work the employee does."},{"s":163.28,"e":170.22,"t":"It's been claimed that workers in industry are more likely to have high absence rates than people who work in offices."},{"s":171.12,"e":176.74,"t":"It's also important to recognise that groups within a single organisation might behave differently."},{"s":189.44,"e":194.32,"t":"Specifically, it's been found that the bigger the group, the higher the levels of absence."},{"s":207.41,"e":211.75,"t":"There is some evidence that absence levels are higher in the public sector."},{"s":235.87,"e":240.11,"t":"However, most recent literature suggests a number of other explanations."},{"s":240.57,"e":246.01,"t":"Firstly, a public sector organisation tends to have a workforce which is larger."},{"s":246.45,"e":255.13,"t":"Also, it tends to employ a higher number of female and older employees, both of which groups are likely to record higher absence rates."},{"s":267.73,"e":274.75,"t":"In addition, it's been found that public sector employers have less of a tendency to dismiss employees for being absent."},{"s":275.21,"e":281.37,"t":"And all of these could be additional or alternative reasons for higher absence rates in the public sector."}]},"4":{"1":[{"s":48.72,"e":50.08,"t":"Yes, good morning."},{"s":50.32,"e":52.68,"t":"I'm looking for an apartment to rent."},{"s":53.94,"e":55.46,"t":"Is that here in Birmingham?"},{"s":57.18,"e":60.56,"t":"I'll just take some personal details if I may."},{"s":61.22,"e":63.6,"t":"So, if I can just take your name?"},{"s":66.04,"e":69.2,"t":"And can I have your present address, please?"},{"s":69.26,"e":76.82,"t":"Well, we're staying with friends at present, so the address is 354 Forest Road."},{"s":76.9,"e":79.5,"t":"Is that Forest with one R?"},{"s":97.22,"e":99.8,"t":"And if I could just ask your occupation?"},{"s":100.72,"e":106.34,"t":"I'm a dentist and my wife's a teacher, but she's at home at present looking after the children."},{"s":107.4,"e":109.92,"t":"So, I'll just put your occupation."},{"s":111.1,"e":115.82,"t":"Well, now I'll take some details about the kind of property you're looking for."},{"s":115.52,"e":119.16,"t":"You said you're looking for an apartment, is that right?"},{"s":121.0,"e":123.22,"t":"So, how many bedrooms do you want?"},{"s":124.28,"e":126.04,"t":"And did you want it furnished?"},{"s":128.62,"e":132.1,"t":"Well, that gives you quite a bit more choice, so that's good."},{"s":132.54,"e":135.7,"t":"And what's the maximum rent you'd be prepared to pay?"},{"s":136.0,"e":145.3,"t":"Well, we'd like to stay under £600 if possible, but we could go up to £650 for the right place."},{"s":146.58,"e":149.38,"t":"So, do you have any other definite requirements?"},{"s":149.62,"e":153.8,"t":"Well, coming back to the bedrooms, they have to be doubles, both of them."},{"s":155.38,"e":156.92,"t":"I'll make a note of that."},{"s":196.64,"e":202.89,"t":"So, are you looking for something straight away?"},{"s":203.19,"e":205.77,"t":"I assume you are if you're staying with friends."},{"s":205.97,"e":208.15,"t":"Well, as soon as possible, yes."},{"s":208.43,"e":215.05,"t":"Well, it's October 17th today, so we're probably looking at November 1st at the earliest."},{"s":216.35,"e":222.31,"t":"Well, I'd have preferred something in October, but OK, let's put that date down for now."},{"s":223.57,"e":225.91,"t":"Now, is there anything else you'd like?"},{"s":226.19,"e":232.85,"t":"Well, our last flat had a garage, but actually, we never used it, so I'm not really worried about that."},{"s":232.55,"e":235.11,"t":"But we'd like a balcony if possible."},{"s":234.81,"e":237.35,"t":"It's nice not to be too shut in."},{"s":237.79,"e":241.33,"t":"You'll find most modern apartments do have one."},{"s":241.03,"e":243.91,"t":"It's only the converted properties that don't."},{"s":243.61,"e":247.79,"t":"But of course, if you're in an older property, you might have use of a garden."},{"s":247.49,"e":249.69,"t":"Would that be a possible alternative?"},{"s":249.39,"e":252.03,"t":"Oh yes, either of those would be good."},{"s":251.73,"e":254.05,"t":"What about transport?"},{"s":253.75,"e":256.37,"t":"Would you want off-street parking?"},{"s":256.07,"e":262.23,"t":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible."},{"s":267.55,"e":271.49,"t":"You'll want a lounge, and will you want a separate dining room?"},{"s":271.73,"e":273.37,"t":"Well, not really."},{"s":273.21,"e":278.63,"t":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that."},{"s":278.81,"e":282.55,"t":"That might be difficult, but I'll make a note of it anyway."}],"2":[{"s":68.24,"e":71.7,"t":"Welcome to Radio OK, your community radio station."},{"s":72.12,"e":77.12,"t":"After our recent bad storm, we have Councillor Phil Evans joining us to tell us about the clean-up effort."},{"s":78.6,"e":79.9,"t":"Thanks for having me."},{"s":80.32,"e":82.78,"t":"Well, we had some pretty severe weather at the weekend."},{"s":83.16,"e":85.84,"t":"Thankfully, it wasn't quite as bad as last year's storm."},{"s":94.1,"e":99.62,"t":"But having said that, a much larger number of homes have been damaged this year due to flash flooding near the creek."},{"s":100.04,"e":104.38,"t":"Those of you who have experienced flooding, we ask you to be especially careful."},{"s":113.48,"e":118.8,"t":"You won't have any electricity at the moment, but we are working as fast as we can to get it reconnected."},{"s":118.5,"e":125.98,"t":"When it comes to cleaning up your garden, you might be tempted to just throw dead branches and so on into your normal garbage bin."},{"s":127.26,"e":132.1,"t":"We're asking people to simply stack them outside on the footpath ready for Council collection."},{"s":132.6,"e":135.3,"t":"We plan to cut them up and use them for composting."},{"s":144.3,"e":150.06,"t":"Instead, we'll be issuing vouchers that you can use to get food from any of the nominated restaurants."},{"s":150.54,"e":152.74,"t":"Just come to the Council office to collect them."},{"s":153.38,"e":156.9,"t":"We've had an overwhelming number of people offering to help out."},{"s":157.22,"e":161.62,"t":"Anyone who would like to volunteer, please don't call the Council office directly."},{"s":177.0,"e":181.18,"t":"We'll be assessing the drinking water regularly so that there's no risk of contamination."},{"s":181.84,"e":187.0,"t":"Just be aware that local wildlife can be forced out of their natural habitat in this weather."},{"s":187.22,"e":191.96,"t":"Let the Council know of any unusual sightings so we can safely relocate them."},{"s":192.2,"e":198.96,"t":"It may seem that mosquitoes are around in abundance right now, but the actual population is usual for this time of year."},{"s":236.53,"e":240.37,"t":"Now we'll give you some information about key areas in the town."},{"s":281.99,"e":285.55,"t":"Hopefully, it won't be long before you'll be able to drive there again."},{"s":285.51,"e":291.31,"t":"Before the storm, we had hoped to begin work on modernising the bikeway that runs along the river."},{"s":291.63,"e":295.71,"t":"We were particularly looking forward to having bike storage facilities installed."},{"s":296.27,"e":301.83,"t":"While the bikeway itself is okay, unfortunately the area around it is covered in water."},{"s":302.07,"e":308.25,"t":"So we've postponed our work there indefinitely and I'm afraid it's now unlikely that this will ever go ahead."},{"s":308.97,"e":310.89,"t":"Well, that's everything for now."},{"s":311.13,"e":313.21,"t":"I'll be back with a further update tomorrow."}],"3":[{"s":44.48,"e":45.84,"t":"Do come in."},{"s":46.88,"e":50.68,"t":"I understand you wanted to see me about changing courses?"},{"s":59.36,"e":60.82,"t":"Right then, Sally."},{"s":61.14,"e":63.84,"t":"And what course are you doing at the present?"},{"s":63.86,"e":65.4,"t":"It's Economic History."},{"s":66.82,"e":68.22,"t":"And when did you start?"},{"s":81.86,"e":87.08,"t":"Well, there are several that I've thought about, but what I'd like to do most is politics."},{"s":87.48,"e":90.4,"t":"Well, that is a very popular course."},{"s":90.5,"e":95.68,"t":"I know, and there might not be places, but… Sure, I'll certainly take a note of that."},{"s":96.4,"e":98.02,"t":"But what about another option?"},{"s":98.12,"e":107.14,"t":"Well, I had thought of changing course completely and trying business studies, but then I realised it wasn't really me, so I thought of philosophy."},{"s":162.78,"e":164.78,"t":"Oh no, I realise that."},{"s":164.94,"e":168.32,"t":"And actually, I would like to have a go at staying with Economic History."},{"s":169.18,"e":171.08,"t":"Yeah, well, let's see."},{"s":171.62,"e":174.38,"t":"Let's talk through some of the problems you've been having."},{"s":175.16,"e":178.78,"t":"What would you say was your major difficulty on the course?"},{"s":179.16,"e":184.16,"t":"I think I'd have to say the worst thing is that I find the lectures difficult."},{"s":189.52,"e":192.38,"t":"Well, I did try recording lectures, you know."},{"s":192.2,"e":194.1,"t":"Yes, that's a good idea."},{"s":193.8,"e":195.82,"t":"And did you find it helped?"},{"s":195.98,"e":198.96,"t":"To a certain extent, but..."},{"s":212.74,"e":215.48,"t":"I could certainly ask if I could join."},{"s":215.78,"e":218.2,"t":"I'm sure you'd find it a help."},{"s":220.76,"e":223.46,"t":"Well, this really worried me at the beginning."},{"s":224.08,"e":226.18,"t":"The fact that there are not enough tutorials."},{"s":226.82,"e":228.28,"t":"Not enough tutorials."},{"s":229.08,"e":231.0,"t":"Did you talk to your tutor about it?"},{"s":230.84,"e":234.2,"t":"Yeah, that was what I thought was the best strategy."},{"s":234.36,"e":236.28,"t":"It's what all the student handbooks say."},{"s":238.2,"e":244.78,"t":"Well, really, just that she's very busy and I have to fit in tutorials when she's available, which is really difficult."},{"s":247.22,"e":251.36,"t":"Why don't you try arranging meetings in advance?"},{"s":251.98,"e":254.14,"t":"Well, I can certainly give it a go."},{"s":254.74,"e":260.96,"t":"But I suppose the thing that's been really upsetting me recently is my bad assignment grade."},{"s":261.48,"e":263.3,"t":"How many have you had back?"},{"s":265.0,"e":267.68,"t":"Well, you could say it was early days yet."},{"s":267.8,"e":272.64,"t":"Well, for the last assignment, which we've just handed in, I did more background reading."},{"s":277.0,"e":282.2,"t":"Well, another strategy might be visiting student services."},{"s":282.62,"e":285.4,"t":"They offer a lot of advice on assignment preparation."},{"s":285.5,"e":287.9,"t":"Well, I didn't want to bother them."},{"s":287.66,"e":289.04,"t":"That's their job."},{"s":294.2,"e":300.04,"t":"Now, what I've done here is to keep a record of our discussions and suggested strategies."},{"s":310.14,"e":314.96,"t":"And if not, then we can start thinking seriously about those alternative courses."},{"s":315.02,"e":317.0,"t":"So you'd like me to come back?"},{"s":318.2,"e":320.62,"t":"Let's say in a month's time."},{"s":328.08,"e":329.42,"t":"And will I meet with you?"},{"s":329.72,"e":332.16,"t":"I'm afraid I'll be on leave at that time."},{"s":332.32,"e":336.42,"t":"But I'll leave this record on file and you'll be meeting our senior advisor."},{"s":341.78,"e":346.04,"t":"Well, I do hope things improve, Sally, and that the change won't be necessary."},{"s":346.0,"e":349.62,"t":"And if it is, well, we can think about that later."}],"4":[{"s":72.64,"e":75.78,"t":"Good morning and welcome to the Walden Gallery."},{"s":76.18,"e":82.1,"t":"In today's open lecture, I'm going to be talking about our collection of perfume ornaments, or containers."},{"s":82.38,"e":89.76,"t":"These beautiful objects now form a significant part of the museum's collection and are very popular with the public."},{"s":89.68,"e":92.84,"t":"But this has not always been the case."},{"s":119.68,"e":128.58,"t":"Now before I say anything more about the perfume containers, I thought I'd briefly touch on the background to the development of perfumes themselves."},{"s":129.04,"e":133.54,"t":"In the West, perfumery really began as late as the 11th century."},{"s":133.76,"e":142.76,"t":"Bathing and laundering were considered hazardous undertakings because even though there were ample supplies of water, it was often dirty or even infected."},{"s":142.82,"e":151.0,"t":"As a consequence, as you can imagine, the air was heavy with unpleasant smells, which had to be countered or covered up."},{"s":170.4,"e":178.5,"t":"I've brought out one ornament from the collection, the oldest one, in fact, from the 14th century, which I'll pass around for you to sample."},{"s":190.8,"e":196.52,"t":"They must have had a powerful aroma in those days because even now you can smell the fragrance."},{"s":218.82,"e":227.2,"t":"But only recently, researchers at our museum have found that they were also believed to significantly raise the spirits of the wearer."},{"s":261.0,"e":268.2,"t":"Let's turn now to have a look at some of the key developments in perfume containers in the last 200 years or so."},{"s":268.66,"e":273.74,"t":"From the late 18th century onwards, the vinaigrette came into vogue."},{"s":274.2,"e":280.96,"t":"The vinaigrette was a miniature box which opened on a hinge, containing a tiny sponge soaked with perfume."},{"s":281.14,"e":285.6,"t":"This was placed under a grill through which you could smell the fragrance."},{"s":285.88,"e":291.64,"t":"It was widely used to carry the highly corrosive scent known as vinegar water, hence the name."},{"s":291.82,"e":299.68,"t":"The outer box could be made of any material, but the lining was gold because the perfume tended to corrode other substances."},{"s":300.92,"e":306.12,"t":"From the mid-19th century, vinaigrettes were replaced by more conventional bottles."},{"s":317.74,"e":321.0,"t":"By now these beautiful objects were more affordable."},{"s":321.72,"e":330.4,"t":"This was the age of the Industrial Revolution in Western Europe, and the bottles were mass-produced and thus available not just to the very wealthy."},{"s":332.4,"e":342.34,"t":"In the last quarter of the 19th century, one company above all became associated with the design and production of perfume bottles, the Tiffany Company."},{"s":342.84,"e":348.9,"t":"They developed a wide range of designs, most notably based on those of the furniture of the period."},{"s":349.44,"e":354.22,"t":"Their particular achievement was their stylish and clever working of crystal."},{"s":363.72,"e":369.24,"t":"Many innovative designs were used in perfume ornaments produced in the 1920s and 30s."},{"s":369.34,"e":372.62,"t":"The most notable was probably the vanity."},{"s":373.0,"e":381.82,"t":"This was an ingeniously designed case used not only for holding perfume, but also makeup, in a whole maze of tiny additional compartments."},{"s":393.04,"e":398.04,"t":"Now, I've brought along a selection of the items in the collection which I've set out here."},{"s":398.78,"e":400.68,"t":"If you'd like to come and gather..."}]},"5":{"1":[{"s":88.3,"e":92.04,"t":"You will see that there is an example that has been done for you."},{"s":101.75,"e":103.75,"t":"Hi Susie, it's Steve."},{"s":106.39,"e":107.93,"t":"I'm fine, thanks."},{"s":108.65,"e":114.83,"t":"Actually, I've got to attend a conference in July in Tucson, Arizona, and I was hoping you could give me a few tips."},{"s":117.07,"e":118.39,"t":"I sure am."},{"s":118.79,"e":123.49,"t":"Tucson's not my hometown though, but it's definitely worth seeing."},{"s":124.17,"e":126.11,"t":"What's the weather like around then?"},{"s":126.47,"e":129.85,"t":"Is it true it's about 40 degrees centigrade in the daytime?"},{"s":129.89,"e":133.53,"t":"That's right, and not less than 25 at night."},{"s":133.93,"e":136.39,"t":"A bit different from England in July."},{"s":139.56,"e":146.7,"t":"The temperature during the day will be 40 degrees, so 40 has been written in the space."},{"s":163.91,"e":165.91,"t":"Hi Susie, it's Steve."},{"s":168.53,"e":170.07,"t":"I'm fine, thanks."},{"s":170.85,"e":177.01,"t":"Actually, I've got to attend a conference in July in Tucson, Arizona, and I was hoping you could give me a few tips."},{"s":181.11,"e":185.61,"t":"Tucson's not my hometown though, but it's definitely worth seeing."},{"s":186.35,"e":188.31,"t":"What's the weather like around then?"},{"s":188.69,"e":191.99,"t":"Is it true it's about 40 degrees centigrade in the daytime?"},{"s":192.05,"e":195.55,"t":"That's right, and not less than 25 at night."},{"s":195.99,"e":198.55,"t":"A bit different from England in July."},{"s":200.15,"e":202.47,"t":"I was wondering what to take with me."},{"s":202.71,"e":204.87,"t":"I won't need warm clothes then, will I?"},{"s":204.93,"e":214.61,"t":"Well, you'll find that everywhere is air-conditioned, and it can feel quite cold sometimes, so a jacket would be a good idea."},{"s":224.89,"e":230.39,"t":"My conference is only for a couple of days, so I was wondering what I could do in Tucson."},{"s":230.79,"e":233.73,"t":"Well, it's a beautiful position."},{"s":233.43,"e":239.49,"t":"I'd hire a car in Tucson, and then follow the trails in the desert."},{"s":240.29,"e":242.29,"t":"Okay, I'm writing all this down."},{"s":242.51,"e":243.97,"t":"Any other tips?"},{"s":246.07,"e":248.65,"t":"Well, there are lots of museums."},{"s":249.29,"e":252.23,"t":"The usual thing, like wildlife and history."},{"s":253.01,"e":259.79,"t":"But I think the most interesting is the Space Museum, so my advice would be to go there."},{"s":260.71,"e":262.61,"t":"Hmm, what else?"},{"s":263.15,"e":266.15,"t":"Well, there are plenty of walks you can do."},{"s":266.41,"e":274.07,"t":"The town itself is great, and there are plenty of places you can eat and drink when you get too hot and tired."},{"s":274.17,"e":276.19,"t":"Any chance of a game of golf?"},{"s":278.01,"e":280.45,"t":"There are loads of courses around Tucson."},{"s":328.61,"e":332.19,"t":"If you've got time, why don't you visit my parents?"},{"s":332.31,"e":333.93,"t":"They'd love to see you."},{"s":335.53,"e":336.85,"t":"Can you give me their address?"},{"s":347.41,"e":349.57,"t":"How do you spell that?"},{"s":366.27,"e":373.85,"t":"The town's in northern Arizona, and it's named after a hunter in the area in the early 1800s."},{"s":374.29,"e":378.59,"t":"He used to make a living shooting animals around there for their skins."},{"s":380.97,"e":383.31,"t":"So, is it full of old buildings?"},{"s":384.15,"e":389.49,"t":"Well, the post office is the oldest, as it was built in 1881."},{"s":389.51,"e":396.11,"t":"But there was a big fire in 1901, and most of the town was burnt down."},{"s":396.71,"e":399.17,"t":"But it didn't take them long to rebuild."},{"s":398.87,"e":403.83,"t":"Oh, and the famous Route 66 goes through the town."},{"s":404.19,"e":406.09,"t":"That was built in 1926."},{"s":406.83,"e":409.41,"t":"So, when exactly are you going?"},{"s":409.83,"e":413.35,"t":"The conference is from the 1st to the 2nd of July."},{"s":413.71,"e":415.89,"t":"Will your parents be at home after that?"},{"s":417.09,"e":420.99,"t":"They wouldn't miss the 4th of July, Independence Day."},{"s":422.73,"e":424.23,"t":"So, lots of fireworks?"},{"s":424.41,"e":426.51,"t":"As soon as the sun goes down."},{"s":426.21,"e":429.95,"t":"People come from miles around to see them."},{"s":430.49,"e":432.41,"t":"Why don't you give my parents a call?"},{"s":439.71,"e":442.15,"t":"I'm sure they'd love to have you."},{"s":445.71,"e":452.49,"t":"And really, you shouldn't be in Arizona without taking a trip to the Grand Canyon for a few days."},{"s":453.87,"e":455.23,"t":"I've got a leaflet here."},{"s":456.23,"e":459.01,"t":"I took a friend there last summer."},{"s":459.41,"e":461.21,"t":"She had a great time."},{"s":463.41,"e":469.49,"t":"It says here that there are a lot of tours you can take when you get there."},{"s":469.57,"e":471.77,"t":"Someone told me you could take a helicopter."},{"s":474.49,"e":481.99,"t":"That tour takes about one and a half hours, and there are seven a day to choose from."},{"s":484.71,"e":489.73,"t":"You get a really good idea of the huge size of the canyon from up there."},{"s":491.11,"e":493.15,"t":"Any chance I can get down to the river?"},{"s":493.47,"e":494.95,"t":"I'm quite good in a canoe."},{"s":496.43,"e":499.03,"t":"Yes, you can do that, too."},{"s":501.55,"e":504.59,"t":"Ah, yes, there's an all-day trip."},{"s":504.95,"e":511.57,"t":"They provide you with waterproof clothes, but they recommend you bring sun cream."},{"s":512.01,"e":514.71,"t":"You'll really need it down on the river."},{"s":515.61,"e":518.61,"t":"Well, that should keep me busy for a few days."},{"s":520.95,"e":522.79,"t":"I'll ring you again just before I go."}],"2":[{"s":56.78,"e":58.38,"t":"Good evening, everyone."},{"s":58.8,"e":60.32,"t":"Thanks for coming in."},{"s":71.96,"e":76.9,"t":"After the tour, we'll introduce you to some of the book promotions we have this month."},{"s":77.56,"e":80.04,"t":"Have you all got a copy of the map?"},{"s":80.4,"e":83.96,"t":"Okay, let's move to the store entrance."},{"s":90.67,"e":98.17,"t":"There are the two cashiers straight ahead, and on our right, close to the wall, is a large area divided into sections."},{"s":118.11,"e":121.61,"t":"The books here range from design to renovation."},{"s":122.43,"e":126.67,"t":"And at the back of this section, we have a small selection of gardening books."},{"s":135.87,"e":141.09,"t":"But we ultimately decided to have it at the back there, and it's well signposted."},{"s":142.55,"e":150.73,"t":"Straight ahead, and directly behind the cashiers, there's the magazine and newspaper stand, which is closest to us."},{"s":151.03,"e":158.29,"t":"Behind this, you can see two sections side by side, history on one side and biographies on the other."},{"s":158.74,"e":164.37,"t":"In our other stores, these sections are usually located at the very back."},{"s":164.07,"e":171.35,"t":"But sales haven't been great, so to try to attract more interest, we decided to make them more visible."},{"s":172.11,"e":178.91,"t":"Also within this central area, just behind biographies, we've placed our two fiction sections."},{"s":188.53,"e":196.17,"t":"You'll see over in the far left-hand corner of the store, we have our coffee shop, which has become very popular."},{"s":196.93,"e":202.87,"t":"Behind this, running right along the back of the store, we've introduced a reading area."},{"s":203.89,"e":207.95,"t":"We've added chairs and cushions to create a cosy atmosphere."},{"s":207.65,"e":214.83,"t":"And as you move around the store later, you'll see this comfortable seating idea in other parts of the shop."},{"s":214.87,"e":221.29,"t":"And finally, immediately to the left of the entrance, you'll see self-help books."},{"s":236.81,"e":239.21,"t":"I'll let you have a browse around in a minute."},{"s":277.18,"e":282.14,"t":"Next, I'd like to quickly introduce you to some of the new books we have in stock."},{"s":288.34,"e":293.78,"t":"It's a wonderful story, set in early Australia, and I thoroughly recommend it."},{"s":294.02,"e":298.26,"t":"It includes some beautiful drawings based on the artwork of the era."},{"s":298.92,"e":300.96,"t":"Next is The Running Boy."},{"s":301.46,"e":306.08,"t":"It's about a boy who gets himself into some difficult situations at school."},{"s":312.28,"e":317.5,"t":"He's currently working on his second novel, a crime story aimed at the adult market."},{"s":318.16,"e":321.08,"t":"I'm sure that will definitely be worth waiting for."},{"s":321.8,"e":329.38,"t":"The next book I have here is The Hidden Code, which won several prizes at the last book convention."},{"s":330.06,"e":336.66,"t":"Marketed as a book for older children, it deals with realistic problems faced by young people today."},{"s":336.94,"e":339.24,"t":"Basically, it's a work of fiction."},{"s":340.56,"e":346.78,"t":"It's something that should also be read by every parent, not just the younger members of the family."},{"s":347.82,"e":352.6,"t":"And finally, my personal favourite, The Orange Moon."},{"s":353.28,"e":360.3,"t":"This is the final book in a set of novels about the lives of a fictional group of friends living in outback Australia."},{"s":360.92,"e":368.0,"t":"I hear this is being adapted to a movie, suitable for the whole family, which I'm sure will be very popular."}],"3":[{"s":64.24,"e":69.04,"t":"I want to talk about essays today and what the requirements are for this university."},{"s":73.12,"e":77.14,"t":"So, let's look at those two sample essays I gave you last week."},{"s":77.64,"e":81.7,"t":"I asked you to read them and to think about their strong and weak points."},{"s":82.22,"e":86.0,"t":"Do either of you have any general comments or questions about the first one?"},{"s":87.74,"e":93.74,"t":"Well, the writer's made it quite clear what his own views are about this subject."},{"s":94.12,"e":98.5,"t":"But I thought in academic essays you weren't supposed to do that."},{"s":98.84,"e":105.7,"t":"I thought you were meant to present all the different arguments and just appear to be neutral about which one you think is best."},{"s":106.02,"e":110.12,"t":"Students do sometimes come down quite firmly on one particular side."},{"s":110.32,"e":115.66,"t":"And that's OK, as long as they can show that they've given balanced consideration to all the issues."},{"s":117.26,"e":119.58,"t":"John, you're looking a bit uncertain."},{"s":121.12,"e":125.44,"t":"Well, what if you don't feel as sure about the debate as this student?"},{"s":125.78,"e":129.3,"t":"There's another type of conclusion that's valid when you're writing at this level."},{"s":129.64,"e":132.88,"t":"People don't have to come down strongly on a particular side."},{"s":141.86,"e":145.12,"t":"And then they return to the title of the assignment."},{"s":146.64,"e":151.46,"t":"And I'd say that it's a good idea to use some of the actual words that are in the title."},{"s":151.72,"e":154.36,"t":"It shows the reader that you're still on track."},{"s":156.24,"e":160.58,"t":"Tony, can I just ask you something about the bibliography?"},{"s":162.46,"e":170.66,"t":"This person's used italics when he refers to book titles in the reference section, but I thought we had to underline them."},{"s":171.02,"e":174.98,"t":"Actually, he's done it in the way we set out in the University Study Guide."},{"s":175.3,"e":177.72,"t":"That is the appropriate convention for titles."},{"s":189.46,"e":192.74,"t":"And once people are used to it, they don't generally have a big problem with it."},{"s":194.62,"e":197.72,"t":"You mentioned the University Study Guide."},{"s":198.0,"e":201.4,"t":"I looked in there to see what it said about quotations."},{"s":202.38,"e":208.08,"t":"The essays got a lot of quite long ones, and I was a bit surprised by that."},{"s":208.36,"e":210.3,"t":"I thought we weren't supposed to do that."},{"s":210.28,"e":216.02,"t":"But using a range of quotations is a way of showing that you have actually read quite widely, isn't it?"},{"s":216.52,"e":217.98,"t":"Well, not really."},{"s":218.34,"e":223.74,"t":"Unfortunately, some students just pick out extracts to quote without actually reading the whole thing."},{"s":224.34,"e":227.6,"t":"It's really a matter of using quotations appropriately."},{"s":228.18,"e":235.26,"t":"I've marked essays in the past where literally every fourth or fifth sentence has been a quote, and that definitely isn't acceptable."},{"s":235.76,"e":243.0,"t":"You have to read widely, but you should be assimilating what you've read, and in general, presenting the ideas in your own words."},{"s":246.96,"e":250.28,"t":"Particularly where there are definitions involved, as there are here."},{"s":250.68,"e":259.58,"t":"Generally speaking, I'd say that you need to be aware of words within the essay title itself that are possibly contentious, terms that need defining."},{"s":260.24,"e":263.52,"t":"For instance, this one here has the word culture in it."},{"s":263.74,"e":270.26,"t":"Now, although you probably have a rough idea of what that term means, you might not be able to articulate it very well."},{"s":269.96,"e":275.18,"t":"So, why not cite someone else's definition, rather than dream one up yourself?"},{"s":279.4,"e":282.94,"t":"What about the way the writer discusses research findings?"},{"s":283.04,"e":288.2,"t":"One thing that struck me was the approach of the student to some of the things he'd read."},{"s":288.44,"e":294.06,"t":"He says things like, we aren't given enough evidence, or we don't know how he got his results."},{"s":306.54,"e":311.36,"t":"But I've always felt that it's just up to me to go to the primary sources and find out."},{"s":311.36,"e":317.52,"t":"It is important that you feel free to say if there are reasons why you can't make a clear judgement about something."},{"s":317.98,"e":320.22,"t":"But you don't have to, not at this level."},{"s":320.68,"e":323.06,"t":"It's almost as if we just take things for granted."},{"s":372.42,"e":375.76,"t":"Now, let's look at the second essay then."},{"s":376.16,"e":379.7,"t":"First of all, this essay title is in the form of a question, isn't it?"},{"s":380.26,"e":382.48,"t":"Did you think this student answered the question?"},{"s":384.1,"e":386.84,"t":"Good, because really that's the bottom line."},{"s":387.18,"e":390.52,"t":"The minimum criterion for an assignment is relevance."},{"s":392.32,"e":397.88,"t":"Sometimes people don't seem to see the words on the page, but you have to be very focused."},{"s":398.42,"e":401.42,"t":"Secondly, what about the overall structure?"},{"s":401.76,"e":403.96,"t":"Would you say that the essay is well-structured?"},{"s":404.84,"e":406.5,"t":"Yes, I would."},{"s":407.06,"e":414.38,"t":"I mean, sometimes writers mix different subtopics up, so it's quite difficult to follow the logic of the essay."},{"s":414.32,"e":417.7,"t":"But here I think they're separated very clearly."},{"s":418.06,"e":419.56,"t":"Do you agree, John?"},{"s":421.08,"e":422.96,"t":"I mean, it is very clear."},{"s":423.34,"e":427.08,"t":"But is it OK to use subheadings and bullet points like this?"},{"s":427.24,"e":431.06,"t":"I mean, in things like reports, they can be very useful, I know."},{"s":431.22,"e":433.9,"t":"But is it all right to use them in academic essays?"},{"s":434.18,"e":439.72,"t":"Well, my general feeling is that it's best just to use paragraphs to signal changes of topic."},{"s":449.88,"e":456.5,"t":"One thing I thought was really good about this essay was the way the writer always gives examples to support statements."},{"s":456.96,"e":459.82,"t":"He never just assumes that explanations are enough."},{"s":461.48,"e":462.88,"t":"I was going to mention it myself."},{"s":463.22,"e":465.68,"t":"As you say, it's very helpful for the reader."},{"s":465.38,"e":471.94,"t":"Another thing that helps the reader is the way he uses words and phrases to connect ideas."},{"s":472.26,"e":475.52,"t":"You mean things like however and on the other hand?"},{"s":476.36,"e":479.48,"t":"And finally, in addition… Yes."},{"s":479.62,"e":482.3,"t":"That really is one of the hallmarks of a good essay."},{"s":482.78,"e":490.0,"t":"The content is the most important thing, of course, but there's no doubt that language can make the content clearer, or otherwise, for the reader."},{"s":490.26,"e":496.98,"t":"Now, you may feel at this early stage that your writing skills are rusty, but reading is the key, I think."}],"4":[{"s":78.64,"e":81.28,"t":"Welcome back to this series of linguistics lectures."},{"s":81.72,"e":86.18,"t":"Today, I will be talking about the idea of inventing a universal language."},{"s":88.52,"e":91.82,"t":"Well, most human languages were never invented."},{"s":92.16,"e":94.56,"t":"Instead, they evolved over time."},{"s":94.94,"e":99.16,"t":"And the result is, you know, they're irregular and difficult to learn."},{"s":99.66,"e":104.28,"t":"So for centuries, people have dreamed of inventing a perfect universal language."},{"s":115.86,"e":122.96,"t":"Scholars have found evidence that around 900 languages have been invented over the centuries in various parts of the world."},{"s":123.66,"e":131.82,"t":"But the linguist Erika Ockrent believes that the exact figure is unclear because she suspects many of these languages are now lost."},{"s":131.98,"e":133.52,"t":"No record of them survives."},{"s":134.8,"e":140.66,"t":"The first really serious attempt to invent a language was made by William Spencer in the 17th century."},{"s":140.36,"e":146.16,"t":"Like so many others, he was frustrated by the irregularities in all existing languages."},{"s":146.96,"e":150.84,"t":"Accuracy was particularly important for Spencer because he wrote books."},{"s":151.02,"e":152.52,"t":"His subject was science."},{"s":153.28,"e":161.06,"t":"As a result, he wanted to create a language where words had only one meaning, so everyone would understand precisely what they meant."},{"s":173.26,"e":179.48,"t":"However, this attempt failed, mostly because he couldn't describe complex ideas in this way."},{"s":180.16,"e":185.2,"t":"So Spencer went back to using the alphabet, but he grouped words together in a different way."},{"s":185.92,"e":191.84,"t":"When his dictionary was published in 1668, the words weren't classified in alphabetical order."},{"s":192.5,"e":199.6,"t":"What he'd done was, he'd used the same system with which plants were divided up into groups based on their type."},{"s":204.19,"e":211.53,"t":"Another important attempt to invent a universal language was made by Ludwig Zamenhof, who was born in 1859."},{"s":215.67,"e":220.25,"t":"He grew up speaking Polish, English, French, German, and Russian."},{"s":220.91,"e":227.67,"t":"So, rather than create a completely new language, he mixed together five or six existing European languages."},{"s":239.13,"e":246.13,"t":"He also thought that most European languages were too complicated, which meant that it was very difficult for people to learn them."},{"s":259.73,"e":264.61,"t":"Then, finally, he published a book introducing his language to the world in 1887."},{"s":265.37,"e":270.49,"t":"Unfortunately, like other invented languages, no one was very interested at first."},{"s":270.93,"e":273.75,"t":"So, again, Zamenhof used an interesting approach."},{"s":282.79,"e":284.57,"t":"Many people were surprised."},{"s":299.09,"e":304.43,"t":"In the 20th century, an Australian named Bruce Goldie tried something completely different."},{"s":305.23,"e":311.01,"t":"Goldie thought that a universal language would be easier to use if the starting point for each word was a picture."},{"s":311.83,"e":318.85,"t":"Goldie spent more than 20 years designing his new language and eventually published a book giving all the details in 1949."},{"s":334.11,"e":337.89,"t":"It wasn't until the 1970s that his language had some success."},{"s":338.33,"e":344.25,"t":"This was in Canada, in fact, where it was used to teach a group of disabled children in a hospital to read."},{"s":349.11,"e":351.11,"t":"So what can we say in conclusion?"},{"s":351.79,"e":358.55,"t":"Well, the truth is all attempts to create a universal language have failed and there are a number of reasons for this."},{"s":359.23,"e":364.13,"t":"Firstly, most universal languages have been seen as rather technical and plain."},{"s":364.55,"e":368.01,"t":"They are not good at conveying emotions so they've never been very popular."},{"s":368.61,"e":376.81,"t":"Another reason is the spread of English as a global language in the 20th century, particularly resulting from the film industry in Hollywood."},{"s":377.69,"e":381.73,"t":"Lastly, the type of people who invented the languages began to change."},{"s":382.19,"e":389.81,"t":"In the past it had been academics, but more recently, the languages have often been created by writers, usually for entertainment."},{"s":390.09,"e":392.07,"t":"So they haven't been taken seriously."}]},"6":{"1":[{"s":96.16,"e":100.0,"t":"You will see that there is an example that has been done for you."},{"s":108.51,"e":110.47,"t":"Hello, Move It Shipping."},{"s":110.65,"e":114.99,"t":"Hi, I'd like a few more details about your services please."},{"s":115.99,"e":122.21,"t":"I've been on your website looking into sending some things abroad when I go away to study next term."},{"s":121.91,"e":129.09,"t":"I see that you provide special empty boxes so that I can pack them myself and you then transport them."},{"s":130.19,"e":132.03,"t":"We provide those free of charge."},{"s":135.54,"e":141.62,"t":"The company provide boxes for packing, so boxes has been written in the space."},{"s":157.57,"e":159.53,"t":"Hello, Move It Shipping."},{"s":159.91,"e":164.01,"t":"Hi, I'd like a few more details about your services please."},{"s":165.07,"e":171.23,"t":"I've been on your website looking into sending some things abroad when I go away to study next term."},{"s":171.75,"e":178.03,"t":"I see that you provide special empty boxes so that I can pack them myself and you then transport them."},{"s":179.15,"e":181.11,"t":"We provide those free of charge."},{"s":180.81,"e":183.77,"t":"And can I ask what goods you can transport?"},{"s":184.27,"e":186.69,"t":"Like, do you take electrical goods?"},{"s":188.73,"e":191.71,"t":"If you've got something like a computer, that's fine."},{"s":191.93,"e":196.77,"t":"But things like washing machines and fridges are too heavy and bulky for our service."},{"s":197.01,"e":199.83,"t":"No, I wouldn't be taking that sort of stuff."},{"s":199.97,"e":203.83,"t":"You can always check with us if there's anything you're not sure about including."},{"s":203.97,"e":206.57,"t":"I was wondering about my bicycle."},{"s":209.31,"e":213.37,"t":"No, that's fine, though we wouldn't be able to take a motorbike."},{"s":214.73,"e":217.17,"t":"Is there anything else you don't take?"},{"s":217.69,"e":226.01,"t":"Well, basically, the service is restricted to what one man can lift, so 40 kilogrammes is the maximum for each package."},{"s":226.43,"e":232.71,"t":"We do have a list of particular things we can't transport on our website, but I'll tell you the main points."},{"s":233.19,"e":242.53,"t":"So, in order to comply with security regulations, we don't take any sort of liquids, and we also don't accept any type of foods."},{"s":243.11,"e":249.35,"t":"And if you provide your own containers, rather than using ours, we only allow certain types."},{"s":249.83,"e":252.51,"t":"So, can I use cardboard containers?"},{"s":252.59,"e":259.35,"t":"Yes, they're OK if they're strong enough, but we won't carry things that have been packed in plastic containers."},{"s":259.37,"e":264.39,"t":"They crack and break so easily that our policy is simply not to take them."},{"s":266.63,"e":274.63,"t":"And once I've packed everything, you can collect my things from my home and deliver them to wherever I live abroad, is that right?"},{"s":274.69,"e":278.13,"t":"Yes, and we do have some special services."},{"s":278.49,"e":285.29,"t":"For example, we can make special arrangements to deliver on Saturdays if that's more convenient for you."},{"s":285.37,"e":289.29,"t":"Or, if you're in a hurry, we have an express delivery option."},{"s":289.85,"e":293.99,"t":"There's a surcharge for these services, of course, but it's very reasonable."},{"s":297.01,"e":304.03,"t":"And what happens if the delivery can't be made for some reason, like if I haven't finalised my accommodation?"},{"s":304.53,"e":306.77,"t":"Can you keep my stuff for me for a few days?"},{"s":306.69,"e":312.03,"t":"Yes, we can arrange storage, though again there would be an extra charge for that."},{"s":350.06,"e":353.2,"t":"And can you give me an idea of your prices?"},{"s":354.9,"e":357.18,"t":"Roughly how much would you want transported?"},{"s":357.82,"e":364.28,"t":"Say, for example, I had 15 boxes, and I've also got a violin."},{"s":364.84,"e":367.94,"t":"That would need packing with special care, I think."},{"s":371.7,"e":375.14,"t":"Yes, and Sweden would be the destination."},{"s":379.3,"e":381.36,"t":"Let me just get that up on the screen."},{"s":394.7,"e":396.56,"t":"And how would I pay that?"},{"s":410.2,"e":416.58,"t":"And at the same time, you'll need to hand over some documentation, so you'll need a copy of your passport."},{"s":419.36,"e":423.48,"t":"So make sure you get that done in advance, and have it ready with you."},{"s":423.96,"e":430.64,"t":"Then there are also some papers you'll need that we'll send you in advance, so that you can get them completed in good time."},{"s":430.34,"e":436.88,"t":"The most important ones are the insurance documents, so you need to have filled in all the..."}],"2":[{"s":57.41,"e":59.31,"t":"Welcome to the cooking school."},{"s":62.27,"e":69.79,"t":"I'm here to give you information about the different tours and classes we offer, as well as to show you our cooking facilities here."},{"s":70.35,"e":72.67,"t":"Our tours and classes are very popular."},{"s":73.17,"e":80.47,"t":"The most popular cooking tour is in the early summer in Northern California, which is famous for its cheeses."},{"s":80.97,"e":87.07,"t":"This four-day tour is special because each student receives one-on-one classes with the master chef."},{"s":87.61,"e":95.17,"t":"Then you'll take part in visits to the great cheese producers of the region, and you'll taste cheeses and see how they are made."},{"s":107.25,"e":111.19,"t":"This cooking vacation takes place in a historic villa."},{"s":111.83,"e":117.19,"t":"There will be time to relax and enjoy the surroundings or to do some sightseeing in the area."},{"s":129.85,"e":135.25,"t":"On the third day, you go to the market, then cook your own dinner with a range of local ingredients."},{"s":142.43,"e":148.63,"t":"This is a three-day tour, where you will be staying in a hotel near the city's famous French Quarter."},{"s":148.69,"e":156.27,"t":"You'll have time to explore on your own before taking a unique city tour on foot, led by a local chef."},{"s":157.21,"e":161.89,"t":"Every afternoon there's a cooking class for the group at your hotel's professional kitchen."},{"s":182.41,"e":184.67,"t":"For big families, this helps a lot."},{"s":185.67,"e":190.23,"t":"Many couples take our Cooking for Two class when their children go off to college."},{"s":190.63,"e":194.33,"t":"We teach how to make meals that are nutritious and elegant."},{"s":194.77,"e":196.17,"t":"They're even a bit romantic."},{"s":197.31,"e":205.89,"t":"In the class called Variations on a Theme, you learn to cook a variety of dishes using a specific ingredient in each."},{"s":206.37,"e":210.93,"t":"For example, in the next class you will prepare meals using lemon."},{"s":211.29,"e":213.93,"t":"The lemon chicken meal is divine."},{"s":251.7,"e":256.14,"t":"I'd like to give you a tour of our beautiful kitchen where the meals are made."},{"s":256.54,"e":258.68,"t":"Our one-day classes meet here."},{"s":259.24,"e":260.68,"t":"Just walk through the entrance."},{"s":261.32,"e":266.38,"t":"Right, now you can see the large preparation table in the middle of the main kitchen."},{"s":267.24,"e":271.08,"t":"This beautiful table is large enough for 12 students to work on."},{"s":271.5,"e":274.08,"t":"This room also has a state-of-the-art oven."},{"s":276.72,"e":282.26,"t":"It's just past the preparation table on the left near the entrance to the hallway."},{"s":290.26,"e":293.22,"t":"We keep non-perishable items in the storage."},{"s":293.92,"e":299.0,"t":"As you exit from the hallway, you'll come into the large demonstration kitchen."},{"s":299.66,"e":305.94,"t":"Here we hold smaller classes, but mainly it's used for cooking demonstrations and tasting events."},{"s":306.94,"e":310.28,"t":"The last thing I want to point out is our utensil cabinet."},{"s":310.76,"e":312.76,"t":"It sits right next to the exit."},{"s":313.28,"e":318.66,"t":"It contains a variety of cooking pots and pans and an amazing range of forks and spoons."},{"s":319.78,"e":322.42,"t":"Please feel free to stay around the school to check out our..."}],"3":[{"s":80.92,"e":83.86,"t":"It's one of the articles on the reading list."},{"s":84.04,"e":86.16,"t":"It's about bricks made from waste."},{"s":86.3,"e":88.38,"t":"Is that the one about bitu blocks?"},{"s":88.34,"e":89.72,"t":"Yes, that's right."},{"s":90.54,"e":93.58,"t":"Apparently they're used as an alternative to concrete blocks."},{"s":98.94,"e":101.12,"t":"Yeah, I read it a couple of weeks ago."},{"s":102.48,"e":105.28,"t":"It's going to be really useful for our next assignment."},{"s":105.58,"e":107.84,"t":"Yes, but I'm not doing that option."},{"s":112.88,"e":118.34,"t":"I really enjoyed it and think I might even look into the topic for my dissertation."},{"s":119.32,"e":127.98,"t":"Before I read it, I'd been getting rather bored of all these green innovations in building, using all manner of waste materials."},{"s":136.92,"e":140.8,"t":"It's not as simple as it sounds, of course, but it's a great idea."},{"s":142.88,"e":145.9,"t":"Of course, I knew that because of the way they're made."},{"s":145.92,"e":152.08,"t":"They're extremely stable and the early tests indicate that they're as good as concrete blocks in terms of their weight."},{"s":152.36,"e":156.52,"t":"But I didn't expect them to do so well on water absorption tests."},{"s":156.9,"e":161.08,"t":"And there were some interesting points about their manufacture, weren't there?"},{"s":167.62,"e":171.44,"t":"And they haven't had to develop any new methods of manufacture."},{"s":171.52,"e":177.98,"t":"Yeah, they essentially use existing ones, which is great because that means they won't require massive amounts of new investment."},{"s":210.82,"e":214.44,"t":"I think it said 17 to 18 per cent by value."},{"s":214.92,"e":220.38,"t":"I know that sounds pretty poor, but it's a good foundation to start making improvements on, don't you think?"},{"s":260.63,"e":264.71,"t":"What did you think about the rival to bitchy blocks, veggie blocks?"},{"s":264.65,"e":267.89,"t":"Yeah, bricks made out of waste cooking oil."},{"s":268.79,"e":271.81,"t":"But it did say they could be quite smelly, you know."},{"s":272.97,"e":276.01,"t":"That's one of the drawbacks bitchy blocks don't have."},{"s":276.25,"e":280.33,"t":"But the article said veggie blocks were very popular with certain architects."},{"s":280.39,"e":282.21,"t":"I presume because of cost?"},{"s":283.55,"e":288.13,"t":"But actually veggie blocks come out at the same price and they take longer to make."},{"s":288.65,"e":290.95,"t":"The thing is they look prettier."},{"s":304.73,"e":308.69,"t":"So there are advantages and disadvantages with both types."},{"s":309.79,"e":314.89,"t":"So how do you think these innovations will change practises in the construction industry?"},{"s":315.37,"e":319.85,"t":"Well, I think bitchy blocks have the potential to make a huge difference."},{"s":322.21,"e":324.37,"t":"Basically builders are always going to be cautious."},{"s":326.33,"e":327.75,"t":"Architects are a different matter."},{"s":327.91,"e":330.05,"t":"They like to experiment with new ideas."},{"s":331.83,"e":333.51,"t":"What about veggie blocks?"},{"s":333.77,"e":336.01,"t":"Did architects cooperate in their trials?"},{"s":336.07,"e":339.49,"t":"There was a bit of interest there, but not significant."},{"s":340.17,"e":344.13,"t":"I get the impression veggie blocks won't catch on as well as bitchy blocks."},{"s":345.51,"e":353.71,"t":"I think the key to commercial success will be things like tax breaks for any companies producing materials incorporating recycled materials."},{"s":353.71,"e":355.05,"t":"Yes, that's true."},{"s":355.59,"e":357.85,"t":"It'll be interesting to see what happens anyway."}],"4":[{"s":92.05,"e":99.09,"t":"The site is backed by a range of mountains to the north, overlooking a green, fertile plain to the south."},{"s":100.09,"e":105.09,"t":"Let me first give you an idea of the history of the area and the growth of the city."},{"s":106.05,"e":115.59,"t":"The first evidence we have of human settlement in the Trimora area is of hunter-gatherers around 12,000 years ago."},{"s":144.73,"e":152.09,"t":"Under the Romans, it became very prosperous and traded in grain, olives, and pottery."},{"s":153.41,"e":161.05,"t":"Then, in 518 A.D., an earthquake destroyed Trimora, and the city was abandoned."},{"s":176.29,"e":185.31,"t":"The first report on the ruins dates back to around 1706, when a French explorer passed through the area."},{"s":186.09,"e":190.03,"t":"He thought that what he was seeing were the ruins of a castle."},{"s":217.71,"e":223.19,"t":"The first remains to be excavated were identified as those of the market."},{"s":223.77,"e":231.89,"t":"Archaeologists were trying to establish how trade was organised here and the type of goods which were commonly bought and sold."},{"s":232.95,"e":238.19,"t":"In and around this area, various examples of silver coins have come to light."},{"s":245.47,"e":249.47,"t":"The public squares were paved, as were the main streets."},{"s":250.51,"e":256.69,"t":"There is also some proof to suggest that textile production was an important industry."},{"s":257.33,"e":266.81,"t":"The huge prosperity during this period was helped by the fact that the city was responsible for provisioning the Roman army in the eastern region."},{"s":271.95,"e":277.67,"t":"Now what I'd like to do is talk about some of the more important buildings in some detail."},{"s":278.89,"e":281.33,"t":"First of all, the Doric House."},{"s":281.91,"e":287.61,"t":"This Greek building is located to the east of the city, near the copper mines."},{"s":288.13,"e":292.19,"t":"This building is where the local population would come to get their water."},{"s":315.03,"e":323.37,"t":"In Roman times, the theatre appears to have been extended and may have been able to take up to 5,000 spectators."},{"s":324.85,"e":330.29,"t":"In the southwestern corner of the city are the remains of an elegant stairway."},{"s":330.85,"e":334.05,"t":"It dates back to about 37 AD."},{"s":335.03,"e":341.97,"t":"The stairway is decorated with sculptures of lions, as opposed to bears, found in other parts of the site."},{"s":342.75,"e":346.19,"t":"This is possibly because of trading links with Africa."},{"s":355.83,"e":360.47,"t":"Here, a huge statue of an emperor from the Roman period was excavated."},{"s":361.41,"e":367.03,"t":"It appears to have been carved in pieces and then taken to the site and put together."},{"s":381.73,"e":385.97,"t":"During the dig, I was responsible for many..."}]},"7":{"1":[{"s":83.72,"e":86.2,"t":"Could you help me with a quote for a visit to Australia?"},{"s":86.52,"e":88.02,"t":"Yes, have a seat."},{"s":88.56,"e":93.06,"t":"Now, if I could get a name from you first, then I can set up a quotation form."},{"s":99.82,"e":104.46,"t":"Now, we'd be looking at going during the school holidays, the mid-year ones."},{"s":104.16,"e":105.94,"t":"That's June then, is it?"},{"s":105.8,"e":107.7,"t":"No, it's July this year."},{"s":108.66,"e":110.98,"t":"And what dates are you thinking of?"},{"s":110.72,"e":112.1,"t":"Let me see."},{"s":112.06,"e":118.46,"t":"We want to go for five days and we could go any time from the 1st to the 14th."},{"s":119.3,"e":122.4,"t":"And whereabouts in Australia are you thinking of?"},{"s":122.42,"e":126.04,"t":"We were thinking of flying to Brisbane and then staying somewhere near there."},{"s":126.1,"e":128.58,"t":"So the Gold Coast then."},{"s":128.82,"e":130.16,"t":"That's a lovely area."},{"s":136.44,"e":139.32,"t":"And now, what sort of accommodation are you thinking of?"},{"s":139.1,"e":147.24,"t":"Well, we had in mind an apartment, thinking that hotels are too expensive, and even motels not perhaps as child-friendly as having your own space."},{"s":147.9,"e":149.78,"t":"I'll have a look at what we've got."},{"s":211.49,"e":214.83,"t":"There's lots of information in there about the amusement parks."},{"s":214.91,"e":221.99,"t":"The three main ones are Dream World, which has some scary roller coaster rides, as well as zoo animals."},{"s":221.97,"e":224.27,"t":"So that one sounds OK for all ages."},{"s":232.77,"e":238.27,"t":"And then there's also Movie World, which has actors dressed up as famous film characters."},{"s":238.19,"e":240.93,"t":"My kids don't watch much TV or video."},{"s":241.15,"e":243.27,"t":"I don't think they'd be so into that."},{"s":248.93,"e":252.55,"t":"You can see all kinds of creatures there and get some good photographs."},{"s":254.11,"e":258.67,"t":"Yes, but they're usually asleep and hidden in the treetops during the day."},{"s":258.61,"e":260.67,"t":"But the crocodiles are amazing."},{"s":260.87,"e":264.23,"t":"It's easy to get right up to the fence to get close-ups of them."},{"s":263.93,"e":265.87,"t":"I suppose there are kangaroos."},{"s":265.79,"e":270.59,"t":"Yes, but they're kept in a distant paddock, so can be quite hard to spot."},{"s":270.85,"e":272.89,"t":"Certainly sounds as if you know the place well."},{"s":272.95,"e":274.67,"t":"Yeah, I've been many times."},{"s":275.21,"e":279.79,"t":"Now, I'm searching on my computer here for a suitable place for you to stay."},{"s":280.63,"e":283.13,"t":"What amenities would you like to be near?"},{"s":283.63,"e":288.39,"t":"Well, we don't want to be close to any bars or clubs because of the noise at night."},{"s":288.71,"e":292.57,"t":"We'll need to be within walking distance of a shop to buy food and so on."},{"s":292.27,"e":297.19,"t":"And I guess most people tell you they want to be in beachfront accommodation, do they?"},{"s":304.75,"e":307.75,"t":"And now, what facilities are important to you?"},{"s":307.79,"e":309.73,"t":"Would you like a babysitter for the evenings?"},{"s":328.33,"e":330.05,"t":"What about a parking space?"},{"s":332.55,"e":338.67,"t":"There must be facilities available for washing clothes, either in the unit or a communal one, it doesn't matter which."},{"s":339.41,"e":344.15,"t":"Quite a lot of places have indoor rooms with play equipment for the little ones."},{"s":343.85,"e":345.67,"t":"Would you be interested in that?"},{"s":345.63,"e":348.43,"t":"Yes, that would be useful, especially if it's a rainy day."},{"s":348.65,"e":351.39,"t":"Oh, I'll have a look on the database."}],"2":[{"s":53.4,"e":56.3,"t":"Hello, and welcome to Reynolds Electrical."},{"s":56.78,"e":63.22,"t":"I'm Cathy Meredith, and I'm in charge of your training programme during the month you're going to spend with us."},{"s":63.48,"e":66.3,"t":"Let me start by telling you a little about the company."},{"s":67.06,"e":70.02,"t":"The name Reynolds comes from Tony Reynolds."},{"s":72.88,"e":79.5,"t":"When he was only 19, he started a small company that manufactured cars."},{"s":79.76,"e":83.78,"t":"This was a failure, though, and he gave up in 1927."},{"s":84.34,"e":93.56,"t":"He then trained as an electrician, and in the following year, rented a small workshop and set up a new company, Reynolds Electrical."},{"s":106.92,"e":112.02,"t":"There was a cinema here, which had to be demolished, and new buildings were put up."},{"s":112.66,"e":117.0,"t":"Of course, in those days, it was quite common to have factories close to town centres."},{"s":118.38,"e":122.18,"t":"The company has been more and more successful in the last few years."},{"s":122.74,"e":125.92,"t":"The main reason is a change in the pattern of sales."},{"s":139.14,"e":145.1,"t":"Because of this success, we're feeling confident about the future, and we've got some exciting plans."},{"s":145.54,"e":150.56,"t":"We're now constructing a second factory, so that we can increase production."},{"s":150.88,"e":157.42,"t":"We're also replacing our existing production machinery, and making improvements to all the offices."},{"s":167.42,"e":174.06,"t":"So earlier this year, we were delighted when we received an award for making a big reduction in waste."},{"s":174.34,"e":177.94,"t":"Our policy is to recycle as much as we can."},{"s":213.98,"e":217.92,"t":"Right, now I'll give you an idea of what you'll be doing in the next few days."},{"s":218.46,"e":226.46,"t":"You'll spend most of this week with different members of our staff, working alongside them so that you can learn what their job involves."},{"s":226.86,"e":232.94,"t":"And we'll get together at 3 o'clock every afternoon to focus on a different part of our work."},{"s":233.3,"e":241.2,"t":"Every Monday we have a meeting of people from different parts of the company, and I'd like you to take part in this afternoon's meeting."},{"s":253.68,"e":261.68,"t":"Tomorrow afternoon, Tuesday, I'll introduce you to the IT department, and they'll update you about the changes to our website."},{"s":261.38,"e":266.24,"t":"This is important because a growing number of people want to buy online."},{"s":267.14,"e":272.64,"t":"Then on Wednesday, we'll talk about our contact with those very important people, customers."},{"s":273.22,"e":275.74,"t":"Without them, of course, we'd soon go out of business."},{"s":276.32,"e":283.84,"t":"And that discussion will cover all sorts of things, from advertising to research into what sort of people buy our products."},{"s":284.64,"e":293.18,"t":"The next afternoon, Thursday, we'll focus on recruitment, and how we try to make sure we have the best staff to meet our needs."},{"s":293.64,"e":297.84,"t":"We seem to be doing well because mostly they stay with us for several years."},{"s":298.82,"e":305.24,"t":"And finally, for this week at least, on Friday, something that I think you'll find more interesting than it sounds."},{"s":305.88,"e":314.04,"t":"And that's how we ensure we have sufficient money coming in to pay our bills and other expenses, such as wages."},{"s":315.06,"e":318.6,"t":"Right, now, are there any questions before I go on?"}],"3":[{"s":90.76,"e":95.42,"t":"I've got some ideas for what to include in mine, but I'd like to hear about yours."},{"s":110.24,"e":116.56,"t":"Oh, I was going to pick out the works that I think show creative thinking, but maybe you're right."},{"s":116.28,"e":120.48,"t":"What are you going to include to show your understanding of design?"},{"s":120.98,"e":123.64,"t":"I think I'm going to include that flyer I did."},{"s":123.88,"e":126.26,"t":"That publicity flyer for the music festival?"},{"s":126.56,"e":128.16,"t":"Yes, that was great."},{"s":128.78,"e":131.64,"t":"I'm hoping to use my health and safety poster."},{"s":133.88,"e":139.64,"t":"Some people are including photos of modern buildings, but I'm not so sure about photos."},{"s":139.34,"e":143.92,"t":"Anyway, we've also got to show we've explored one medium in depth."},{"s":143.84,"e":146.58,"t":"Well, what about choosing drawing?"},{"s":146.82,"e":150.14,"t":"That series we both did of the human body would be good, you know."},{"s":150.16,"e":152.28,"t":"The set of pictures showing a man running?"},{"s":152.18,"e":156.5,"t":"Yes, they demonstrate that we can show a human body in action."},{"s":156.9,"e":161.36,"t":"I think they'd be more impressive than those drawings we did of household objects."},{"s":162.78,"e":171.3,"t":"The household objects would show we can draw details precisely and position things on the paper effectively, but they were just static."},{"s":175.9,"e":178.18,"t":"To be honest, I don't think so."},{"s":188.38,"e":191.56,"t":"Pity, because you've dealt with it in a very unusual way."},{"s":193.54,"e":196.94,"t":"Now, we need to think about the portfolio as a whole."},{"s":198.96,"e":200.86,"t":"Did the tutor say anything about that?"},{"s":215.02,"e":220.02,"t":"Some students recommend saving the best piece till last, but I don't agree."},{"s":219.88,"e":221.6,"t":"No, nor do I."},{"s":221.56,"e":228.0,"t":"But everyone says it's a good idea to get someone else to look at the portfolio just before we submit it."},{"s":228.2,"e":233.7,"t":"Of course, our art teacher will comment on it as we go along, but who else are you going to ask?"},{"s":233.62,"e":239.34,"t":"There's a sculptor who lives near me, and my parents know him, so that's who I'm going for."},{"s":287.02,"e":293.32,"t":"Now, our tutor said it's important to make sure the reason for including each piece in our portfolio is clear."},{"s":293.78,"e":297.22,"t":"I think I've more or less decided about that for my portfolio."},{"s":298.28,"e":300.54,"t":"I haven't thought about it at all."},{"s":300.92,"e":302.3,"t":"What have you decided?"},{"s":302.32,"e":305.26,"t":"Well, like my design for a book cover."},{"s":305.54,"e":311.78,"t":"I just had a very simple design based on the book's title in this unusual handwritten script."},{"s":312.3,"e":318.42,"t":"So, my reason for including that is it's a piece which shows the presentation of writing in design."},{"s":319.26,"e":324.64,"t":"Then I did some work on designing jewellery, and I'm including that in my portfolio too."},{"s":324.34,"e":330.44,"t":"So, is that to show how well you can express yourself using different media, like metal?"},{"s":330.9,"e":333.42,"t":"That's not why I'm including it, no."},{"s":333.74,"e":340.98,"t":"What I actually learned from doing the jewellery was the importance of precision, getting each little thing just right."},{"s":341.22,"e":343.92,"t":"So, that's the reason I'm giving for including it."},{"s":353.96,"e":358.24,"t":"At first, I was going to include that because I like the smooth scales of the fish."},{"s":358.26,"e":363.12,"t":"But in the end, I decided it's an example of something that was completely my own idea."},{"s":364.6,"e":366.66,"t":"Then there was the advertisement."},{"s":366.9,"e":372.8,"t":"I did an ad for a hotel, a warm, cosy scene with an illustration of an open fire."},{"s":373.56,"e":379.08,"t":"We had to show we could convey a feeling that matched the image of the product, didn't we?"},{"s":379.32,"e":384.94,"t":"I did one for a fruit juice drink, trying to give an impression of vitality and energy."},{"s":385.82,"e":388.58,"t":"Well, now, shall we get on with actually..."}],"4":[{"s":72.38,"e":76.74,"t":"Welcome to today's lecture about hospital gardens and their medical benefits."},{"s":77.34,"e":81.42,"t":"Recently, a group of architects were interviewed about health care facilities."},{"s":90.62,"e":95.94,"t":"Of course, the idea that a garden can be good for our health is not exactly new."},{"s":111.32,"e":118.0,"t":"In his study, Schwartz reviewed the medical records of people recovering from surgery at a suburban hospital."},{"s":134.54,"e":142.94,"t":"In fact, at the time, studies carried out in Europe showed that the conditions in hospital can have serious physical consequences."},{"s":143.68,"e":148.12,"t":"These studies showed that hospitals contributed to people's levels of stress."},{"s":149.48,"e":157.7,"t":"Fortunately, as the evidence implicating hospitals increased, the amount of data suggesting that gardens can encourage healing grew too."},{"s":169.46,"e":175.94,"t":"This is shown in physiological changes in electrical activity, most obviously in the heart."},{"s":193.24,"e":200.86,"t":"Importantly, as research into this field has grown, it has shown that not all gardens are equally effective in the healing process."},{"s":200.56,"e":212.76,"t":"In 1995, Marcus Cooper and landscape architect Mark Bennett analysed the physical layout of several hospital gardens and carried out observations of their daily use."},{"s":224.5,"e":228.92,"t":"They also found that what people liked most were gardens that had a fountain."},{"s":244.18,"e":247.38,"t":"What you can do in the gardens is important as what you see."},{"s":248.22,"e":257.26,"t":"The results of behavioural map studies in which researchers observe visitors' actions while in a garden suggested gardens need several different things to be effective."},{"s":267.06,"e":268.42,"t":"That's important in hospitals."},{"s":280.42,"e":286.26,"t":"And lastly, they also wanted naturalistic landscaping that would also bring birds into the area."},{"s":300.3,"e":306.04,"t":"Middle-aged adults look for peace and quiet while older adults are more likely to seek stimulation."},{"s":320.1,"e":328.08,"t":"To help ensure that outdoor areas promote as much healing as possible gardens should be planned taking science and aesthetic design into account."}]},"8":{"1":[{"s":98.46,"e":103.3,"t":"Hello, I've come in because I've got some problems in the flat I'm renting."},{"s":109.0,"e":113.42,"t":"I've been renting the flat at 13 Polworth Road for three months now."},{"s":115.2,"e":116.7,"t":"I'll just get the details."},{"s":117.62,"e":118.94,"t":"Ah, yes, here we are."},{"s":119.26,"e":120.76,"t":"Are you alone in the flat?"},{"s":120.46,"e":126.22,"t":"No, I originally rented it with a friend, but now my cousin is there."},{"s":126.28,"e":128.24,"t":"Right, so there's two of you."},{"s":130.24,"e":134.22,"t":"Loads of things have gone wrong or are not working."},{"s":134.52,"e":138.42,"t":"And my contract says the landlord is responsible for them."},{"s":138.34,"e":139.68,"t":"Yes, that's right."},{"s":151.08,"e":153.26,"t":"How do I get hold of him?"},{"s":153.64,"e":155.66,"t":"I've got the contact details here."},{"s":155.68,"e":157.4,"t":"I'll write them down for you."},{"s":157.46,"e":161.32,"t":"But anyway, just for our records, I should make a list of the problems."},{"s":161.9,"e":165.24,"t":"Do you know how long they normally take to fix things?"},{"s":165.34,"e":169.5,"t":"I'm afraid you'll have to wait till next week before they can come over."},{"s":171.62,"e":174.46,"t":"Don't they do things more quickly if they're urgent?"},{"s":174.16,"e":176.3,"t":"Not in my experience."},{"s":176.96,"e":185.26,"t":"Now, just looking through your contract here, it says you are expected to pay £50 towards the cost of anything caused by wear and tear."},{"s":185.3,"e":187.56,"t":"Yes, I realised that."},{"s":187.64,"e":189.04,"t":"That's not the problem."},{"s":189.46,"e":194.68,"t":"But I am worried about a couple of things getting worse over the next week."},{"s":194.94,"e":201.08,"t":"Well, in that case, you can get a private company to fix it and get the money back from the landlord."},{"s":201.3,"e":205.16,"t":"I can give you a list of names and you can try to get them out today."},{"s":206.48,"e":208.18,"t":"I think I'll have to do that."},{"s":209.02,"e":211.84,"t":"Now, where can the landlord get hold of you?"},{"s":211.88,"e":214.4,"t":"We've only got your college phone number."},{"s":216.76,"e":222.8,"t":"It's very difficult, but you could leave a message on my mobile if I'm in class."},{"s":224.14,"e":226.08,"t":"I'll give you the number, shall I?"},{"s":284.84,"e":288.0,"t":"Now, can you tell me exactly what's gone wrong?"},{"s":288.2,"e":295.3,"t":"Yeah, well, first of all, there's a window in the bathroom that wouldn't open."},{"s":295.68,"e":297.88,"t":"The paint seemed to be stuck."},{"s":298.28,"e":303.12,"t":"We've managed to get it open, though I don't know what damage it's caused."},{"s":304.62,"e":308.6,"t":"Yes, the landlord may want to check that the lock on it still works."},{"s":314.12,"e":318.4,"t":"But it may be worth another look, so I'll ask him to do that too."},{"s":320.26,"e":326.98,"t":"Then we've noticed that the lights keep flickering, so I'm worried it means there's a problem with the electricity."},{"s":327.92,"e":333.94,"t":"Because we've also noticed that the washing machine keeps stopping and starting in the middle of a wash."},{"s":333.82,"e":338.3,"t":"Well, that'll need looking at separately by a washing machine repair company."},{"s":347.0,"e":349.06,"t":"The main switch may need replacing."},{"s":351.28,"e":357.62,"t":"Actually, if we're getting an electrician out for that, he could look over the heating system before the winter sets in, couldn't he?"},{"s":357.78,"e":360.9,"t":"It was new last year, though, so it shouldn't break down."},{"s":360.6,"e":362.14,"t":"That would be a good idea."},{"s":363.04,"e":365.52,"t":"The only other thing is in the hall."},{"s":365.22,"e":372.14,"t":"The carpet had started curling up at the edges where the door opens, and we've had to stick it down."},{"s":380.28,"e":382.14,"t":"That's not very satisfactory."},{"s":384.1,"e":385.58,"t":"I'm really sorry about this."},{"s":386.14,"e":389.58,"t":"Well, as long as it can all be sorted quickly."}],"2":[{"s":63.22,"e":68.15,"t":"Good afternoon, listeners."},{"s":68.29,"e":70.47,"t":"Thanks for tuning in to 4KB."},{"s":70.65,"e":75.69,"t":"Jane Lewis is with us from Tourism Queensland to tell us about the annual Queensland Festival."},{"s":79.35,"e":82.87,"t":"So much is going on for the next couple of weeks in our festival."},{"s":82.57,"e":90.69,"t":"Here in the state's capital of Brisbane, the music tent opens this week, and this will be an event not to be missed."},{"s":102.03,"e":108.31,"t":"Monday is going to be really busy as it's a public holiday and the first day of the event."},{"s":108.61,"e":116.21,"t":"It's going to be lots of fun, but if you're free, it's probably a better option to leave it till Tuesday, unless you love crowds."},{"s":116.73,"e":125.47,"t":"The following day is when the masterclasses take place, and this requires pre-registration, so you can't just turn up, I'm afraid."},{"s":125.55,"e":133.17,"t":"The weekend educational workshops were so popular last year that they have been extended this year."},{"s":140.95,"e":147.89,"t":"If you're learning to play an instrument, these workshops are great fun, so make sure you get along there."},{"s":157.01,"e":161.79,"t":"For the best deal, though, take proof of your home address to any library."},{"s":161.49,"e":166.33,"t":"As a local resident, you will be able to purchase discounted tickets."},{"s":167.37,"e":175.19,"t":"Apart from music, we'll also be celebrating our local history with a special walking tour around Brisbane's city centre."},{"s":175.69,"e":182.57,"t":"Not to be missed on the walk is a tour of Macquarie House, the home of Queensland's first governor."},{"s":201.83,"e":208.89,"t":"No Australian event is complete without a barbie, and I think the Big Barbecue is going to be fantastic."},{"s":220.85,"e":224.59,"t":"As always, the food will be prepared by top local chefs."},{"s":224.83,"e":226.95,"t":"My mouth is watering already."},{"s":227.55,"e":236.89,"t":"I really recommend going along to the Railway Museum during the festival because trains are such an important part of Queensland's history."},{"s":237.25,"e":242.51,"t":"On loan from Queensland Rail at the moment is our very first steam train."},{"s":242.75,"e":249.57,"t":"You won't be able to see it in operation, but you can hop on board and have a meal in the old dining carriage."},{"s":250.33,"e":256.27,"t":"There is also a wonderful display of uniforms that have been worn over the last 100 years."},{"s":302.81,"e":310.89,"t":"If you purchase a family ticket, as well as a trip on the train, you receive a free Australian flag each to wave while aboard."},{"s":311.45,"e":319.23,"t":"There is a small charge for the Ipswich museum tour, but I think it's worth it as it makes an educational day out."},{"s":320.01,"e":326.45,"t":"The documentary film you can see there is interesting and it's well worth the $2 entry fee."},{"s":326.95,"e":334.73,"t":"On the return train journey, the kids get a lovely activity book designed to teach them about the history of the steam train."},{"s":335.37,"e":338.45,"t":"Don't forget to bring your sunscreen and hats."},{"s":338.59,"e":342.07,"t":"It's going to be hot up there in Toowoomba at this time of year."},{"s":342.93,"e":348.69,"t":"And finally, I'm going to tell you about an event called Our Favourite Place."},{"s":348.85,"e":354.75,"t":"This is an opportunity for the public to vote for their favourite spot anywhere in the state."},{"s":355.05,"e":357.09,"t":"Maybe a park or restaurant."},{"s":357.73,"e":361.85,"t":"You can vote even if you're not living in the area at the moment."},{"s":375.55,"e":380.69,"t":"Not much time left, though, so get those votes in as soon as possible."},{"s":380.87,"e":385.07,"t":"The winning location will be announced on the last Saturday of the festival."},{"s":389.39,"e":392.47,"t":"So this is a great way to get the whole family involved."},{"s":392.81,"e":394.69,"t":"Well, thank you very much for that, Jane."}],"3":[{"s":47.18,"e":48.8,"t":"Good morning, Simon."},{"s":51.48,"e":53.24,"t":"Just a bit worried about the presentation."},{"s":53.82,"e":57.66,"t":"I wanted to clear up a few points with you, if that's OK, Dr Azari."},{"s":58.58,"e":63.02,"t":"Well, first of all, I wonder if you've got any clearer idea of when it's going to be."},{"s":63.14,"e":68.46,"t":"Lots of the other students are talking about early June, around the 6th to the 7th."},{"s":68.16,"e":70.52,"t":"No, it won't be as early as that."},{"s":70.56,"e":73.42,"t":"It won't be before the open day on the 11th."},{"s":73.76,"e":77.9,"t":"The 14th to the 24th of June is the period we've been pencilling in."},{"s":78.46,"e":80.46,"t":"A bit of a breathing space then."},{"s":81.3,"e":85.68,"t":"And you know that they take place in the lecture hall during the early evening."},{"s":85.46,"e":87.3,"t":"Yes, I remember you saying that."},{"s":88.9,"e":91.04,"t":"Can I also just check the format?"},{"s":91.84,"e":93.28,"t":"There are two parts."},{"s":92.98,"e":99.68,"t":"The first part is about 40 minutes, and that's when you give the presentation to your seminar group."},{"s":101.36,"e":105.08,"t":"And that's followed by a 20-minute interview with Dr Brown."},{"s":105.26,"e":108.4,"t":"That's the part that I'm less clear about, to be honest."},{"s":108.84,"e":111.8,"t":"What sort of thing do I need to have with me for the interview?"},{"s":112.12,"e":114.28,"t":"Just the materials I've used in the presentation?"},{"s":114.5,"e":116.14,"t":"Well, yes, of course."},{"s":116.42,"e":120.74,"t":"And he specifically asked that students bring along a list of objectives as well."},{"s":120.44,"e":123.42,"t":"This will form the basis for the discussion."},{"s":124.88,"e":129.04,"t":"And he's also asking each student to bring along their project outline."},{"s":130.26,"e":134.66,"t":"I suppose it'll help him to see where the different parts of the presentation fit in."},{"s":135.94,"e":141.6,"t":"And because he's also interested in the sources you've drawn on, you should take your book list along."},{"s":142.16,"e":144.32,"t":"Everything that has informed your thinking."},{"s":146.34,"e":148.58,"t":"And will he be giving me feedback?"},{"s":149.36,"e":151.26,"t":"That's the whole point of the exercise."},{"s":151.44,"e":153.44,"t":"You'll get a checklist from him."},{"s":154.24,"e":156.3,"t":"Yes, he'll fill it in on the spot."},{"s":156.72,"e":159.62,"t":"And you'll also get what we call thinking questions."},{"s":160.54,"e":162.86,"t":"We had those for the formative essay, didn't we?"},{"s":205.35,"e":209.13,"t":"And what sort of criteria will he use when giving feedback?"},{"s":209.17,"e":214.69,"t":"Well, basically, the kind of things he'll be looking for are whether you've done wide reading."},{"s":214.79,"e":217.05,"t":"Well, I don't think I'll have any problems with that."},{"s":217.11,"e":219.13,"t":"My book list is six pages long."},{"s":220.29,"e":223.47,"t":"But you also need to demonstrate that you can design research."},{"s":226.13,"e":230.47,"t":"And of course, the usual requirement that you can set out a clear argument."},{"s":233.05,"e":236.95,"t":"And can I ask about stage two after the presentation?"},{"s":237.13,"e":242.99,"t":"Well, if all goes well, which it should, you will need to write your theory chapters."},{"s":244.41,"e":246.43,"t":"I've already started thinking about those."},{"s":247.57,"e":250.73,"t":"And in addition to that, you'll have to do your data analysis."},{"s":251.91,"e":253.49,"t":"Should I be getting on with that now?"},{"s":253.23,"e":254.71,"t":"Don't worry, Simon."},{"s":254.93,"e":257.77,"t":"The best thing is to concentrate on the presentation."},{"s":258.55,"e":259.95,"t":"I'm always looking ahead."},{"s":259.95,"e":264.19,"t":"Well, if you do want further information on that, there's always the website."},{"s":264.11,"e":265.55,"t":"Have you got the address?"},{"s":269.27,"e":271.43,"t":"All one word for student link."},{"s":275.41,"e":276.87,"t":"I feel a lot clearer now."}],"4":[{"s":88.59,"e":91.81,"t":"The subject of my lecture today is child psychology."},{"s":92.33,"e":99.63,"t":"I'm going to talk about research in that area, how it has changed in recent years, and how it's likely to develop in future."},{"s":100.23,"e":104.97,"t":"First of all, there's the way we look at the subject of child psychology itself."},{"s":105.43,"e":110.11,"t":"Traditionally, we used to talk about three different aspects of a child's development."},{"s":110.39,"e":114.63,"t":"Social development, that's how the child relates to other people."},{"s":114.33,"e":119.87,"t":"Cognitive development, how a child reasons or explains things to himself."},{"s":119.91,"e":128.09,"t":"And emotional development, how the child feels about people and things and events in the world around him."},{"s":129.89,"e":136.33,"t":"And those three areas were kept very separate, and different psychologists used to work in different areas."},{"s":136.87,"e":142.49,"t":"But what you have now is the growing realisation that you can't draw those hard and fast boundaries."},{"s":142.87,"e":145.61,"t":"The three aspects are all seen to be connected."},{"s":145.95,"e":147.39,"t":"So that's the first thing."},{"s":149.29,"e":154.17,"t":"In the past, people tended to study behaviour in artificial contexts."},{"s":154.55,"e":157.99,"t":"Take, for example, the type of behaviour referred to as learning."},{"s":158.45,"e":163.47,"t":"Traditionally, it was investigated by studying how animals behave in laboratories."},{"s":164.27,"e":173.71,"t":"But now, thanks to psychologists like Vygotsky, there's a growing realisation that you can't isolate things that happened during childhood."},{"s":181.69,"e":183.47,"t":"Is he with peers?"},{"s":188.71,"e":197.63,"t":"Another far-reaching change that has taken place within the last 20 or 30 years concerns the way children themselves are regarded."},{"s":204.65,"e":207.79,"t":"Let's take the parent-child relationship."},{"s":208.31,"e":211.55,"t":"This was seen as something that parents did to children."},{"s":211.89,"e":215.11,"t":"And if something then went wrong, then you blamed the parents."},{"s":227.43,"e":231.21,"t":"The reason being that our genes also play a part."},{"s":230.91,"e":238.16,"t":"And this brings me to the next point."},{"s":238.52,"e":244.24,"t":"In the past, ideas were very much influenced by the child psychologist, Piaget."},{"s":251.66,"e":255.96,"t":"He meant that they project their own feelings and thoughts onto other people."},{"s":256.46,"e":260.06,"t":"But recently, people have started to listen to other views."},{"s":274.46,"e":279.56,"t":"And she gave examples which illustrate children's awareness of other people very clearly."},{"s":280.12,"e":282.66,"t":"They are not just thinking of themselves all the time."},{"s":283.16,"e":286.16,"t":"And other psychologists have taken up that suggestion."},{"s":286.7,"e":289.52,"t":"And yes, we have no end of examples now."},{"s":290.52,"e":293.48,"t":"Then there's another area where things have changed."},{"s":293.18,"e":299.32,"t":"In the past, we psychologists had a rather lazy attitude towards culture."},{"s":299.68,"e":301.56,"t":"It was a factor that we just ignored."},{"s":314.1,"e":315.52,"t":"Let's take one example."},{"s":315.92,"e":320.06,"t":"The importance of stimulation during the first few weeks of life."},{"s":332.28,"e":338.3,"t":"But a study in Guatemala showed that this is not the case, at least not in all contexts."},{"s":338.78,"e":344.98,"t":"It is the custom for mothers in one area of that country to keep their babies in the house during the first year."},{"s":345.14,"e":349.14,"t":"They never take them out, and they don't encourage visitors or noise."},{"s":355.88,"e":365.14,"t":"I won't go into the reasons for this, but the point is that these babies develop into perfectly normal, healthy, intelligent, bright, and active children."},{"s":365.34,"e":372.66,"t":"And what happens in that first year or so of life apparently has absolutely no negative implications for later development."},{"s":384.26,"e":388.9,"t":"So those are some of the changes that have taken place in psychology in recent years."},{"s":390.94,"e":397.76,"t":"There's already been some very interesting work, which suggests that learning is possible even at the prenatal stage."},{"s":398.08,"e":402.32,"t":"The most obvious example is the infant's ability to recognise voices."},{"s":411.68,"e":414.08,"t":"From that of another female stranger."},{"s":414.48,"e":421.1,"t":"And there's simply no explanation other than that the child has acquired this knowledge in the womb."},{"s":421.88,"e":427.8,"t":"So if I'm asked what's likely to attract a lot of interesting work in future, I'd say it's this combination."}]}};
